import { app, type BrowserWindow } from "electron";
import { IpcListen } from "@qiwork/desktop-runtime/ipcEvents";
import { focusMainWindow } from "./window";
import { parseStoreTab } from "../src/utils/storeTabs";

export type DeepLinkNavigatePayload = {
  path: string;
  search?: string;
};

const DEVICE_COMPLETE = "auth/device-complete";

export function registerDeepLinkHandlers(
  getMainWindow: () => BrowserWindow | null,
): void {
  if (!app.isPackaged) {
    app.setAsDefaultProtocolClient("qiwork", process.execPath, [
      process.argv[1] ?? ".",
    ]);
  } else {
    app.setAsDefaultProtocolClient("qiwork");
  }

  const deliver = (rawUrl: string) => {
    handleDeepLink(rawUrl, getMainWindow);
  };

  app.on("open-url", (event, rawUrl) => {
    event.preventDefault();
    deliver(rawUrl);
  });

  for (const arg of process.argv) {
    if (arg.startsWith("qiwork://")) {
      deliver(arg);
    }
  }
}

export function handleDeepLinkArgv(
  argv: string[],
  getMainWindow: () => BrowserWindow | null,
): void {
  const rawUrl = argv.find((arg) => arg.startsWith("qiwork://"));
  if (rawUrl) {
    handleDeepLink(rawUrl, getMainWindow);
  }
}

export function sendAppNavigate(
  win: BrowserWindow | null,
  payload: DeepLinkNavigatePayload,
): void {
  focusMainWindow(win);
  win?.webContents.send(IpcListen.deepLinkNavigate, payload);
}

function handleDeepLink(
  rawUrl: string,
  getMainWindow: () => BrowserWindow | null,
): void {
  let parsed: URL;
  try {
    parsed = new URL(rawUrl);
  } catch {
    return;
  }
  if (parsed.protocol !== "qiwork:") return;

  const win = getMainWindow();
  const path = `${parsed.hostname}${parsed.pathname}`.replace(/\/$/, "");

  if (path === DEVICE_COMPLETE) {
    focusMainWindow(win);
    win?.webContents.send(IpcListen.authDeviceComplete);
    return;
  }

  if (path === "store") {
    const safeTab = parseStoreTab(parsed.searchParams.get("tab"));
    sendAppNavigate(win, { path: "/store", search: `?tab=${safeTab}` });
  }
}
