import { app } from "electron";
import { SIDECAR_STOP_TIMEOUT_MS } from "@qiwork/desktop-runtime/updatePolicy";
import { sidecar } from "./sidecar";
import {
  emitInstallError,
  installReadyUpdate,
  isUpdateReady,
} from "./updater";
import { permitExit, revokeExit } from "./window";

let quitInFlight = false;
let interceptQuit = false;

export function enableQuitIntercept(): void {
  interceptQuit = true;
}

export function shouldInterceptQuit(): boolean {
  return interceptQuit && !quitInFlight;
}

function forceQuit(): void {
  permitExit();
  sidecar.stop();
  app.quit();
}

export async function requestAppQuit(options: {
  applyUpdate: boolean;
  requireReady?: boolean;
}): Promise<void> {
  if (quitInFlight) return;
  quitInFlight = true;

  const ready = isUpdateReady();
  if (options.requireReady && !ready) {
    emitInstallError("更新包尚未就绪。");
    quitInFlight = false;
    return;
  }

  try {
    if (options.applyUpdate && ready) {
      const stopped = await sidecar.stopAndWait(SIDECAR_STOP_TIMEOUT_MS);
      if (stopped) {
        permitExit();
        const started = await installReadyUpdate();
        if (started) return;
      } else {
        emitInstallError("后端未在退出前停止，已取消安装。");
      }
      if (options.requireReady) {
        revokeExit();
        quitInFlight = false;
        return;
      }
      forceQuit();
      return;
    }

    permitExit();
    await sidecar.stopAndWait(SIDECAR_STOP_TIMEOUT_MS);
    app.quit();
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    emitInstallError(message);
    if (options.requireReady) {
      revokeExit();
      quitInFlight = false;
      return;
    }
    forceQuit();
  }
}
