import path from "node:path";
import { app, type WebContents } from "electron";
import { fileURLToPath, pathToFileURL } from "node:url";
import { HOST_APP_SCHEME } from "./renderer-schemes";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

export function isDev(): boolean {
  return !app.isPackaged;
}

/** Directory containing compiled main/preload (dist-electron). */
export function electronDistDir(): string {
  return path.join(__dirname);
}

export function preloadPath(): string {
  return path.join(electronDistDir(), "preload.cjs");
}

export function updatePromptPreloadPath(): string {
  return path.join(electronDistDir(), "update-prompt-preload.cjs");
}

export function updatePromptPageUrl(): string {
  return hostPageUrl("desktop-update-prompt.html");
}

export function guestPreloadPath(): string {
  return path.join(electronDistDir(), "guest-preload.cjs");
}

export function historyUtilityPath(): string {
  return path.join(electronDistDir(), "guest-history-utility.cjs");
}

function devRendererPageUrl(file: string): string {
  const base =
    process.env.VITE_DEV_SERVER_URL ?? "http://localhost:5173/electron.html";
  return base.replace(/electron\.html.*$/, file);
}

function hostPageUrl(file: string): string {
  if (isDev()) return devRendererPageUrl(file);
  return `${HOST_APP_SCHEME}://localhost/${file}`;
}

/** Dabi rendererRoot: compiled main dir → sibling Vite outDir. */
export function rendererDistRoot(): string {
  return path.join(__dirname, "..", "dist");
}

function rendererDistFile(file: string): string {
  return path.join(rendererDistRoot(), file);
}

/** Tab identity: file:// in prod, Vite in dev. Not the load mechanism. */
function guestPageUrl(file: string): string {
  if (isDev()) return devRendererPageUrl(file);
  return pathToFileURL(rendererDistFile(file)).href;
}

/** Packaged guest WebUI: loadFile only. Host scheme is never used here. */
export function loadGuestRendererPage(wc: WebContents, file: string): void {
  if (wc.isDestroyed()) return;
  if (isDev()) {
    void wc.loadURL(devRendererPageUrl(file));
    return;
  }
  void wc.loadFile(rendererDistFile(file));
}

export function guestToolbarUrl(): string {
  return hostPageUrl("desktop-toolbar.html");
}

export function guestNewtabUrl(): string {
  return guestPageUrl("desktop-newtab.html");
}

export function guestHistoryUrl(): string {
  return guestPageUrl("desktop-history.html");
}

export function guestDownloadsUrl(): string {
  return guestPageUrl("desktop-downloads.html");
}

export function guestCertWarningPage(): string {
  return guestPageUrl("desktop-cert-warning.html");
}

export function loadGuestCertWarning(
  wc: WebContents,
  params: { url: string; host: string; code: string },
): void {
  if (wc.isDestroyed()) return;
  if (isDev()) {
    const next = new URL(devRendererPageUrl("desktop-cert-warning.html"));
    next.searchParams.set("url", params.url);
    next.searchParams.set("host", params.host);
    next.searchParams.set("code", params.code);
    void wc.loadURL(next.toString());
    return;
  }
  void wc.loadFile(rendererDistFile("desktop-cert-warning.html"), { query: params });
}

export function guestInternalKind(
  url: string,
): "newtab" | "history" | "downloads" | null {
  const match = url.match(
    /desktop-(newtab|history|downloads|cert-warning)\.html(?:[?#]|$)/,
  );
  if (match?.[1] === "cert-warning") return null;
  return (match?.[1] as "newtab" | "history" | "downloads" | undefined) ?? null;
}

export function isGuestInternalUrl(url: string): boolean {
  return guestInternalKind(url) != null || /desktop-cert-warning\.html/.test(url);
}

/** Same official.env QIWork Gateway loads for LLMPLAT_API_URL. */
export function officialEnvPaths(): string[] {
  if (isDev()) {
    return [
      path.join(app.getAppPath(), "..", "src", "qiwork", "builtin", "official.env"),
    ];
  }
  const binaries = resourcesBinariesDir();
  return [
    path.join(binaries, "qiwork", "_internal", "qiwork", "builtin", "official.env"),
    path.join(binaries, "qiwork", "qiwork", "builtin", "official.env"),
    path.join(binaries, "qiwork", "builtin", "official.env"),
  ];
}

export function resourcesBinariesDir(): string {
  if (isDev()) {
    return path.join(app.getAppPath(), "build", "binaries");
  }
  return path.join(process.resourcesPath, "binaries");
}

/** Silently synced unpack of a remote guest extension. */
export function userGuestExtensionDir(name: string): string {
  return path.join(app.getPath("userData"), "guest-extensions", name);
}

export function pathEnvKey(): string {
  return process.platform === "win32" ? "Path" : "PATH";
}

export function joinPathEnv(prepend: string[]): string {
  const key = pathEnvKey();
  const existing = process.env[key] ?? "";
  const parts = [...prepend, ...existing.split(path.delimiter).filter(Boolean)];
  return parts.join(path.delimiter);
}
