import { Menu, app } from "electron";
import { resolveAppIconPath } from "./app-icon";

/** Shown in the macOS menu bar, About panel, and Cmd+Tab (dev + prod). */
export const APP_DISPLAY_NAME = "QIWork";

/** Call before `app.whenReady()` — affects userData paths / internal name. */
export function setupApplicationBranding(): void {
  app.setName(APP_DISPLAY_NAME);
}

/** Native macOS About panel (QIWork menu → About QIWork). */
export function setupAboutPanel(): void {
  const iconPath = resolveAppIconPath();
  app.setAboutPanelOptions({
    applicationName: APP_DISPLAY_NAME,
    applicationVersion: app.getVersion(),
    version: app.getVersion(),
    ...(iconPath ? { iconPath } : {}),
  });
}

/**
 * Replace the default Electron-branded application menu on macOS.
 * Note: the global menu bar title comes from Electron.app Info.plist in dev
 * — see scripts/brand-electron-macos.mjs.
 */
export function setupMacApplicationMenu(): void {
  if (process.platform !== "darwin") return;

  const template: Electron.MenuItemConstructorOptions[] = [
    {
      label: app.name,
      submenu: [
        { role: "about" },
        { type: "separator" },
        { role: "hide" },
        { role: "hideOthers" },
        { role: "unhide" },
        { type: "separator" },
        { role: "quit" },
      ],
    },
    { role: "editMenu" },
    { role: "viewMenu" },
    { role: "windowMenu" },
  ];
  Menu.setApplicationMenu(Menu.buildFromTemplate(template));
}
