/** Cursor-style update policy. Main owns the state machine; UI only renders it. */

export type MainUpdateState = "idle" | "checking" | "downloading" | "ready";

export const FIRST_CHECK_DELAY_MS = 30_000;
export const CHECK_INTERVAL_MS = 60 * 60 * 1000;
export const CHECK_INTERVAL_JITTER = 0.1;
export const SIDECAR_STOP_TIMEOUT_MS = 8_000;
export const INSTALL_WATCHDOG_MS = 15_000;

export type RestartMarker = {
  targetVersion: string;
  startedAt: number;
  explicit: boolean;
};

export type RestartResult = {
  success: boolean;
  targetVersion: string;
};

export function canStartCheck(
  state: MainUpdateState,
  installInFlight: boolean,
): boolean {
  return !installInFlight && (state === "idle" || state === "ready");
}

export function canQuitAndInstall(
  state: MainUpdateState,
  installInFlight: boolean,
): boolean {
  return state === "ready" && !installInFlight;
}

const AUTO_OPEN_STEPS = new Set(["available", "downloading", "ready", "error"]);

/** Passive HUD for update progress, staged package, or failure. */
export function canAutoOpenUpdatePrompt(step: string): boolean {
  return AUTO_OPEN_STEPS.has(step);
}

/** Delay only while a package exists but is not staged. ready / download / error open now. */
export function shouldDelayUpdatePrompt(step: string): boolean {
  return step === "available";
}

export function nextPeriodicCheckDelayMs(random = Math.random): number {
  const jitter = 1 + (random() * 2 - 1) * CHECK_INTERVAL_JITTER;
  return Math.round(CHECK_INTERVAL_MS * jitter);
}

export function parseRestartMarker(raw: unknown): RestartMarker | null {
  if (!raw || typeof raw !== "object") return null;
  const rec = raw as {
    targetVersion?: unknown;
    startedAt?: unknown;
    explicit?: unknown;
  };
  if (typeof rec.targetVersion !== "string" || !rec.targetVersion) return null;
  if (typeof rec.startedAt !== "number" || !Number.isFinite(rec.startedAt)) {
    return null;
  }
  return {
    targetVersion: rec.targetVersion,
    startedAt: rec.startedAt,
    explicit: rec.explicit === true,
  };
}

export function reconcileRestart(
  currentVersion: string,
  marker: RestartMarker | null,
): RestartResult | null {
  if (!marker) return null;
  return {
    success: currentVersion === marker.targetVersion,
    targetVersion: marker.targetVersion,
  };
}
