import { app, BrowserWindow } from "electron";
import fs from "node:fs";
import { IpcListen } from "@qiwork/desktop-runtime/ipcEvents";
import type { DesktopUpdaterEvent } from "@qiwork/desktop-runtime/updaterEvent";
import {
  canQuitAndInstall,
  canStartCheck,
  FIRST_CHECK_DELAY_MS,
  INSTALL_WATCHDOG_MS,
  nextPeriodicCheckDelayMs,
  reconcileRestart,
  type MainUpdateState,
} from "@qiwork/desktop-runtime/updatePolicy";
import { showDesktopNotification } from "./notifications";
import { officialEnvPaths } from "./paths";
import { resolveUpdateFeedUrl } from "./updateFeed";
import {
  clearRestartMarker,
  readRestartMarker,
  restartMarkerPath,
  writeRestartMarker,
} from "./updateRestart";

type UpdaterModule = typeof import("electron-updater") & {
  default?: typeof import("electron-updater");
};

let listenersBound = false;
let state: MainUpdateState = "idle";
let installInFlight = false;
let readyVersion: string | undefined;
let checkTimer: ReturnType<typeof setTimeout> | null = null;
let watchdogTimer: ReturnType<typeof setTimeout> | null = null;

function readOfficialEnvText(): string | undefined {
  for (const candidate of officialEnvPaths()) {
    try {
      return fs.readFileSync(candidate, "utf8");
    } catch {
      /* try next */
    }
  }
  return undefined;
}

function restoreSettled(): void {
  if (installInFlight) return;
  state = readyVersion ? "ready" : "idle";
}

function emitUpdater(
  event: DesktopUpdaterEvent,
  win?: BrowserWindow | null,
): void {
  const target =
    win && !win.isDestroyed()
      ? win
      : BrowserWindow.getAllWindows().find((item) => !item.isDestroyed());
  if (!target) return;
  target.webContents.send(IpcListen.updater, event);
}

function versionOf(info: unknown): string | undefined {
  if (!info || typeof info !== "object") return undefined;
  const version = (info as { version?: unknown }).version;
  return typeof version === "string" ? version : undefined;
}

async function loadAutoUpdater() {
  const mod = (await import("electron-updater")) as UpdaterModule;
  const autoUpdater = mod.autoUpdater ?? mod.default?.autoUpdater;
  if (!autoUpdater) {
    throw new Error("electron-updater autoUpdater is unavailable");
  }
  autoUpdater.forceDevUpdateConfig = !app.isPackaged;
  autoUpdater.autoDownload = true;
  autoUpdater.autoInstallOnAppQuit = true;
  const feedUrl = resolveUpdateFeedUrl(process.env, readOfficialEnvText());
  if (feedUrl) {
    autoUpdater.setFeedURL({ provider: "generic", url: feedUrl });
  }
  return autoUpdater;
}

function bindListeners(
  autoUpdater: Awaited<ReturnType<typeof loadAutoUpdater>>,
  win: BrowserWindow,
): void {
  if (listenersBound) return;
  listenersBound = true;

  autoUpdater.on("update-available", (info) => {
    if (state !== "ready") state = "downloading";
    emitUpdater({ kind: "available", version: versionOf(info) }, win);
  });
  autoUpdater.on("update-not-available", () => {
    restoreSettled();
    if (!readyVersion) emitUpdater({ kind: "not-available" }, win);
  });
  autoUpdater.on("download-progress", (progress) => {
    if (state !== "ready") state = "downloading";
    emitUpdater(
      {
        kind: "progress",
        transferred: progress.transferred,
        total: progress.total,
      },
      win,
    );
  });
  autoUpdater.on("update-downloaded", (info) => {
    state = "ready";
    readyVersion = versionOf(info);
    showDesktopNotification("新版本就绪", "版本已经下载完成，重启后立即生效。");
    emitUpdater({ kind: "downloaded", version: readyVersion }, win);
  });
  autoUpdater.on("error", (err) => {
    restoreSettled();
    emitUpdater({ kind: "error", message: err.message }, win);
  });
}

function emitRestartResult(win: BrowserWindow): void {
  const filePath = restartMarkerPath();
  const result = reconcileRestart(app.getVersion(), readRestartMarker(filePath));
  clearRestartMarker(filePath);
  if (!result) return;
  emitUpdater(
    {
      kind: "restart-result",
      success: result.success,
      targetVersion: result.targetVersion,
      message: result.success
        ? undefined
        : "上次更新未完成，当前仍是此版本。",
    },
    win,
  );
}

function scheduleChecks(win: BrowserWindow, delayMs: number): void {
  if (checkTimer) clearTimeout(checkTimer);
  checkTimer = setTimeout(() => {
    void checkForUpdates(win);
    scheduleChecks(win, nextPeriodicCheckDelayMs());
  }, delayMs);
}

function clearWatchdog(): void {
  if (!watchdogTimer) return;
  clearTimeout(watchdogTimer);
  watchdogTimer = null;
}

function startWatchdog(): void {
  clearWatchdog();
  watchdogTimer = setTimeout(() => {
    if (!installInFlight) return;
    installInFlight = false;
    emitUpdater({
      kind: "error",
      message: "安装程序启动后应用仍在运行，请重试。",
      prompt: true,
    });
  }, INSTALL_WATCHDOG_MS);
}

/** Wire electron-updater once, then check the generic feed after startup. */
export async function setupAutoUpdater(win: BrowserWindow): Promise<void> {
  try {
    const autoUpdater = await loadAutoUpdater();
    bindListeners(autoUpdater, win);
    emitRestartResult(win);
    scheduleChecks(win, FIRST_CHECK_DELAY_MS);
  } catch (err) {
    console.warn("[updater] electron-updater not available", err);
  }
}

export async function checkForUpdates(
  win?: BrowserWindow | null,
): Promise<void> {
  if (!canStartCheck(state, installInFlight)) return;
  state = "checking";
  try {
    const autoUpdater = await loadAutoUpdater();
    await autoUpdater.checkForUpdates();
  } catch (err) {
    restoreSettled();
    const message = err instanceof Error ? err.message : String(err);
    emitUpdater({ kind: "error", message }, win);
  }
}

export async function downloadUpdate(
  win?: BrowserWindow | null,
): Promise<void> {
  if (installInFlight || state === "ready") return;
  state = "downloading";
  try {
    const autoUpdater = await loadAutoUpdater();
    await autoUpdater.downloadUpdate();
  } catch (err) {
    restoreSettled();
    const message = err instanceof Error ? err.message : String(err);
    emitUpdater({ kind: "error", message }, win);
  }
}

export function isUpdateReady(): boolean {
  return canQuitAndInstall(state, installInFlight);
}

export function emitInstallError(message: string): void {
  emitUpdater({ kind: "error", message, prompt: true });
}

export async function installReadyUpdate(): Promise<boolean> {
  if (!canQuitAndInstall(state, installInFlight)) {
    emitInstallError("更新包尚未就绪。");
    return false;
  }
  installInFlight = true;
  writeRestartMarker(restartMarkerPath(), {
    targetVersion: readyVersion || app.getVersion(),
    startedAt: Date.now(),
    explicit: true,
  });
  startWatchdog();
  try {
    const autoUpdater = await loadAutoUpdater();
    autoUpdater.quitAndInstall(false, true);
    return true;
  } catch (err) {
    installInFlight = false;
    clearWatchdog();
    clearRestartMarker(restartMarkerPath());
    const message = err instanceof Error ? err.message : String(err);
    emitInstallError(message);
    return false;
  }
}

/** HUD / IPC entry. Prefer requestAppQuit so sidecar can stop first. */
export async function quitAndInstall(): Promise<void> {
  await installReadyUpdate();
}
