function hostOf(raw?: string): string | null {
  if (!raw) return null;
  try {
    return new URL(raw).hostname.toLowerCase();
  } catch {
    return null;
  }
}

function isDouyinHost(host: string | null): boolean {
  return Boolean(host && (host === "douyin.com" || host.endsWith(".douyin.com")));
}

/** Dabi: deny notifications; deny openExternal only when the asking page is Douyin. */
export function allowGuestPermission(
  permission: string,
  details: { requestingUrl?: string; externalURL?: string } = {},
): boolean {
  if (permission === "notifications") return false;
  if (permission === "openExternal") {
    return !isDouyinHost(hostOf(details.requestingUrl));
  }
  return true;
}
