/** Store tab query contract — must match website `StoreTab` in storeDeepLink.ts */
export type StoreTab =
  | "subscription"
  | "packages"
  | "industry_data"
  | "shop_sync";

const STORE_TABS: readonly StoreTab[] = [
  "subscription",
  "packages",
  "industry_data",
  "shop_sync",
] as const;

const STORE_TAB_SET = new Set<string>(STORE_TABS);

export function parseStoreTab(raw: string | null): StoreTab {
  if (raw && STORE_TAB_SET.has(raw)) {
    return raw as StoreTab;
  }
  return "subscription";
}
