import { spawn, type ChildProcess } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import readline from "node:readline";
import { app, type BrowserWindow } from "electron";
import { showDesktopNotification } from "./notifications";
import { cryptoEnv } from "./crypto";
import { isDev, joinPathEnv, pathEnvKey, resourcesBinariesDir } from "./paths";
import type { PlatformLoginHostEnv } from "./platform-login-host";
import { allocateLoopbackPort } from "./sidecarListen";
import { finishedWithin, waitForProcessExit } from "./sidecarWait";
import { parseRuntimeAnnounce } from "./runtimeAnnounce";
import { IpcListen } from "@qiwork/desktop-runtime/ipcEvents";
import {
  emptyRuntimeState,
  reduceRuntimeState,
  type DesktopRuntimeState,
} from "@qiwork/desktop-runtime/runtimeState";

const MAX_CAPTURED_STDERR_CHARS = 4000;
const STDERR_TRUNCATION_MARKER = "\n[...stderr truncated...]\n";
const CONNECT_ANNOUNCE_TIMEOUT_MS = 90_000;
const CAPABILITY_TIMEOUT_MS = 180_000;

type SidecarKind = "backend" | "qiworkconnect";

type CmdSpec = {
  exe: string;
  args: string[];
  cwd: string;
  extraEnv?: NodeJS.ProcessEnv;
};

function trimCapturedStderr(text: string): string {
  if ([...text].length <= MAX_CAPTURED_STDERR_CHARS) return text;
  const chars = [...text];
  const markerLen = [...STDERR_TRUNCATION_MARKER].length;
  const keep = MAX_CAPTURED_STDERR_CHARS - markerLen;
  const head = Math.floor(keep / 2);
  const tail = keep - head;
  return (
    chars.slice(0, head).join("") +
    STDERR_TRUNCATION_MARKER +
    chars.slice(-tail).join("")
  );
}

function findFile(candidates: string[]): string | null {
  return (
    candidates.find((p) => fs.existsSync(p) && fs.statSync(p).isFile()) ?? null
  );
}

export class SidecarManager {
  private generation = 0;
  private gatewayChild: ChildProcess | null = null;
  private connectChild: ChildProcess | null = null;
  private state: DesktopRuntimeState = emptyRuntimeState();
  private gatewayPid: number | null = null;
  private desktopHostEnv: PlatformLoginHostEnv | null = null;
  private connectDeadlineTimer: ReturnType<typeof setTimeout> | null = null;
  private coreDeadlineTimer: ReturnType<typeof setTimeout> | null = null;
  private agentDeadlineTimer: ReturnType<typeof setTimeout> | null = null;
  private expectedBackendPort: number | null = null;
  private expectedConnectPort: number | null = null;

  setDesktopHostEnv(env: PlatformLoginHostEnv): void {
    this.desktopHostEnv = env;
  }

  getRuntimeState(): DesktopRuntimeState {
    return this.state;
  }

  getGatewayPid(): number | null {
    return this.gatewayPid;
  }

  async start(win: BrowserWindow): Promise<void> {
    const gen = ++this.generation;
    this.clearStartupState(gen);
    this.publish(win);

    try {
      const connectPort = await allocateLoopbackPort();
      const backendPort = await allocateLoopbackPort();
      if (!this.isCurrent(gen)) return;

      this.expectedConnectPort = connectPort;
      this.expectedBackendPort = backendPort;
      this.spawnConnect(win, gen, connectPort);
      this.spawnBackend(win, gen, backendPort, connectPort);
      this.armConnectDeadline(win, gen);
      this.armCoreDeadline(win, gen);
    } catch (error) {
      if (!this.isCurrent(gen)) return;
      this.killChild(this.connectChild);
      this.killChild(this.gatewayChild);
      this.failBackend(
        win,
        error instanceof Error ? error.message : String(error),
        "后端启动失败",
      );
    }
  }

  async restart(win: BrowserWindow): Promise<void> {
    this.stop();
    await this.start(win);
  }

  stop(): void {
    this.generation += 1;
    this.clearDeadlines();
    this.killChild(this.connectChild);
    this.killChild(this.gatewayChild);
    this.connectChild = null;
    this.gatewayChild = null;
    this.gatewayPid = null;
    this.expectedBackendPort = null;
    this.expectedConnectPort = null;
  }

  /** SIGTERM children and wait for exit. Does not SIGKILL on timeout. */
  async stopAndWait(timeoutMs: number): Promise<boolean> {
    const children = [this.connectChild, this.gatewayChild].filter(
      (child): child is ChildProcess => Boolean(child),
    );
    if (children.length === 0) {
      this.stop();
      return true;
    }
    const exited = Promise.all(children.map((child) => waitForProcessExit(child)));
    this.stop();
    return finishedWithin(exited, timeoutMs);
  }

  private clearStartupState(generation: number): void {
    this.state = emptyRuntimeState(generation);
    this.gatewayPid = null;
    this.expectedBackendPort = null;
    this.expectedConnectPort = null;
    this.clearDeadlines();
  }

  private isCurrent(gen: number): boolean {
    return gen === this.generation;
  }

  private publish(win: BrowserWindow): void {
    if (win.isDestroyed()) return;
    win.webContents.send(IpcListen.runtimeState, this.getRuntimeState());
  }

  private armConnectDeadline(win: BrowserWindow, gen: number): void {
    this.clearConnectDeadline();
    this.connectDeadlineTimer = setTimeout(() => {
      if (!this.isCurrent(gen)) return;
      this.degradeConnect(
        win,
        `qiworkconnect:${gen} announce timed out; sync degraded`,
      );
    }, CONNECT_ANNOUNCE_TIMEOUT_MS);
  }

  private armCoreDeadline(win: BrowserWindow, gen: number): void {
    this.clearCoreDeadline();
    this.coreDeadlineTimer = setTimeout(() => {
      if (!this.isCurrent(gen) || this.state.caps.core) return;
      this.failBackend(
        win,
        `backend:${gen} core capability timed out`,
        "后端启动超时",
      );
      terminateChildTree(this.gatewayChild, this.gatewayPid);
    }, CAPABILITY_TIMEOUT_MS);
  }

  private armAgentDeadline(win: BrowserWindow, gen: number): void {
    this.clearAgentDeadline();
    this.agentDeadlineTimer = setTimeout(() => {
      if (!this.isCurrent(gen) || this.state.caps.agent !== "starting") return;
      this.state = reduceRuntimeState(this.state, {
        kind: "fail",
        sidecar: "agent",
        message: `backend:${gen} agent capability timed out`,
      });
      this.publish(win);
    }, CAPABILITY_TIMEOUT_MS);
  }

  private clearConnectDeadline(): void {
    if (this.connectDeadlineTimer) {
      clearTimeout(this.connectDeadlineTimer);
      this.connectDeadlineTimer = null;
    }
  }

  private clearCoreDeadline(): void {
    if (this.coreDeadlineTimer) {
      clearTimeout(this.coreDeadlineTimer);
      this.coreDeadlineTimer = null;
    }
  }

  private clearAgentDeadline(): void {
    if (this.agentDeadlineTimer) {
      clearTimeout(this.agentDeadlineTimer);
      this.agentDeadlineTimer = null;
    }
  }

  private clearDeadlines(): void {
    this.clearConnectDeadline();
    this.clearCoreDeadline();
    this.clearAgentDeadline();
  }

  private degradeConnect(win: BrowserWindow, message: string): void {
    if (this.state.connect.state === "degraded") return;
    this.state = reduceRuntimeState(this.state, {
      kind: "connect-degraded",
      message,
    });
    this.clearConnectDeadline();
    console.error(message);
    this.publish(win);
  }

  private applyAnnounce(win: BrowserWindow, gen: number, line: string): void {
    const event = parseRuntimeAnnounce(line);
    if (!event) return;
    if (event.kind === "listen") {
      const expectedPort =
        event.sidecar === "backend"
          ? this.expectedBackendPort
          : this.expectedConnectPort;
      if (expectedPort !== event.port) {
        const message = `${event.sidecar}:${gen} announced unexpected port ${event.port}; expected ${expectedPort}`;
        if (event.sidecar === "backend") {
          this.failBackend(win, message, "后端端口异常");
          terminateChildTree(this.gatewayChild, this.gatewayPid);
        } else {
          this.degradeConnect(win, message);
        }
        return;
      }
      if (event.sidecar === "connect") this.clearConnectDeadline();
    }
    if (event.kind === "cap" && event.cap === "core") {
      this.clearCoreDeadline();
      this.armAgentDeadline(win, gen);
    }
    if (
      (event.kind === "cap" && event.cap === "agent") ||
      (event.kind === "fail" && event.sidecar === "agent")
    ) {
      this.clearAgentDeadline();
    }
    if (event.kind === "fail" && event.sidecar === "backend") {
      this.clearCoreDeadline();
      this.clearAgentDeadline();
    }
    this.state = reduceRuntimeState(this.state, event);
    if (event.kind === "fail" && event.sidecar === "backend") {
      showDesktopNotification(
        "后端启动失败",
        event.message || "backend failed",
      );
    }
    if (event.kind === "fail" && event.sidecar === "agent") {
      console.error(`[backend] agent failed: ${event.message}`);
    }
    this.publish(win);
  }

  private killChild(child: ChildProcess | null): void {
    if (!child || child.killed) return;
    try {
      if (process.platform === "win32" && child.pid) {
        spawn("taskkill", ["/pid", String(child.pid), "/T", "/F"], {
          windowsHide: true,
          stdio: "ignore",
        });
      } else {
        child.kill("SIGTERM");
      }
    } catch {
      /* ignore */
    }
  }

  private spawnConnect(win: BrowserWindow, gen: number, port: number): void {
    const cmd = this.buildConnectCommand();
    const child = spawn(cmd.exe, cmd.args, {
      cwd: cmd.cwd,
      env: {
        ...process.env,
        ...cryptoEnv(),
        ...this.desktopHostEnv,
        ...cmd.extraEnv,
        QIWORKCONNECT_DESKTOP: "1",
        QIWORKCONNECT_PORT: String(port),
        NO_PROXY: "127.0.0.1,localhost,::1,<local>",
        no_proxy: "127.0.0.1,localhost,::1,<local>",
        PYTHONUTF8: "1",
        PYTHONUNBUFFERED: "1",
        PYTHONIOENCODING: "utf-8",
      },
      windowsHide: true,
      stdio: ["ignore", "pipe", "pipe"],
    });
    this.connectChild = child;
    this.watchChild(child, "qiworkconnect", gen, win);
  }

  private spawnBackend(
    win: BrowserWindow,
    gen: number,
    backendPort: number,
    connectPort: number,
  ): void {
    const cmd = this.buildGatewayCommand();
    const child = spawn(cmd.exe, cmd.args, {
      cwd: cmd.cwd,
      env: {
        ...this.buildGatewayEnv(cmd.cwd, connectPort, backendPort),
        ...cmd.extraEnv,
      },
      windowsHide: true,
      stdio: ["ignore", "pipe", "pipe"],
    });
    this.gatewayChild = child;
    this.gatewayPid = child.pid ?? null;
    this.watchChild(child, "backend", gen, win);
  }

  private buildGatewayEnv(
    backendDir: string,
    connectPort: number,
    backendPort: number,
  ): NodeJS.ProcessEnv {
    const env: NodeJS.ProcessEnv = {
      ...process.env,
      ...cryptoEnv(),
      NO_PROXY: "127.0.0.1,localhost,::1,<local>",
      no_proxy: "127.0.0.1,localhost,::1,<local>",
      PYTHONUTF8: "1",
      PYTHONUNBUFFERED: "1",
      PYTHONIOENCODING: "utf-8",
      QIWORK_DESKTOP_APP: "1",
      QIWORK_DESKTOP_PORT: String(backendPort),
      QIWORKCONNECT_URL: `http://127.0.0.1:${connectPort}`,
      [pathEnvKey()]: joinPathEnv([backendDir]),
    };

    if (!isDev()) {
      const binaries = resourcesBinariesDir();
      const py =
        process.platform === "win32"
          ? findFile([
              path.join(binaries, "python-runtime", "python", "python.exe"),
            ])
          : findFile([
              path.join(binaries, "python-runtime", "python", "bin", "python3"),
              path.join(binaries, "python-runtime", "python", "bin", "python"),
            ]);
      if (py) env.QIWORK_DESKTOP_PY_RUNTIME = py;

      const nodeRoot = path.join(binaries, "node-runtime");
      const nodeBin =
        process.platform === "win32"
          ? path.join(nodeRoot, "node.exe")
          : path.join(nodeRoot, "bin", "node");
      if (fs.existsSync(nodeBin)) env.QIWORK_DESKTOP_NODE_RUNTIME = nodeRoot;
    }

    return env;
  }

  private buildConnectCommand(): CmdSpec {
    if (isDev()) {
      const qwcRoot =
        process.env.QIWORKCONNECT_ROOT ??
        path.resolve(app.getAppPath(), "../../QiWorkConnect");
      const apiDir = path.join(qwcRoot, "apps", "api");
      return {
        exe: "uv",
        args: ["run", "python", "-m", "qiworkconnect.desktop_entry"],
        cwd: apiDir,
        extraEnv: { PYTHONPATH: path.join(apiDir, "src") },
      };
    }
    const binaries = resourcesBinariesDir();
    const exeName =
      process.platform === "win32" ? "qiworkconnect.exe" : "qiworkconnect";
    const exe = path.join(binaries, "qiwork", "qiworkconnect", exeName);
    return { exe, args: [], cwd: path.dirname(exe) };
  }

  private buildGatewayCommand(): CmdSpec {
    if (isDev()) {
      const repoRoot = path.resolve(app.getAppPath(), "..");
      return {
        exe: "uv",
        args: ["run", "python", "-m", "qiwork.desktop.entry"],
        cwd: repoRoot,
        extraEnv: { PYTHONPATH: path.join(repoRoot, "src") },
      };
    }
    const binaries = resourcesBinariesDir();
    const exeName = process.platform === "win32" ? "qiwork.exe" : "qiwork";
    const exe = path.join(binaries, "qiwork", exeName);
    return { exe, args: [], cwd: path.dirname(exe) };
  }

  private failBackend(win: BrowserWindow, msg: string, title: string): void {
    if (this.state.backend.state === "failed") return;
    this.clearCoreDeadline();
    this.clearAgentDeadline();
    this.state = reduceRuntimeState(this.state, {
      kind: "backend-exit",
      message: msg,
    });
    showDesktopNotification(title, msg);
    this.publish(win);
  }

  private watchChild(
    child: ChildProcess,
    kind: SidecarKind,
    gen: number,
    win: BrowserWindow,
  ): void {
    let lastStderr = "";
    const label = kind === "backend" ? "backend" : "qiworkconnect";

    const onLine = (line: string, stream: "stdout" | "stderr") => {
      if (stream === "stdout") {
        console.info(`[${label}:${gen}] stdout: ${line}`);
      } else {
        console.error(`[${label}:${gen}] stderr: ${line}`);
        lastStderr = trimCapturedStderr(`${lastStderr}${line}\n`);
      }
      if (!this.isCurrent(gen)) return;
      if (stream === "stdout") this.applyAnnounce(win, gen, line);
    };

    if (child.stdout) {
      readline.createInterface({ input: child.stdout }).on("line", (line) => {
        onLine(line, "stdout");
      });
    }

    if (child.stderr) {
      readline.createInterface({ input: child.stderr }).on("line", (line) => {
        onLine(line, "stderr");
      });
    }

    child.on("error", (err) => {
      if (!this.isCurrent(gen)) return;
      const msg = `${label} spawn error: ${err.message}`;
      if (kind === "backend") {
        this.failBackend(win, msg, "后端启动失败");
        return;
      }
      this.degradeConnect(win, `[${label}:${gen}] ${msg}`);
    });

    child.on("exit", (code, signal) => {
      if (!this.isCurrent(gen)) return;
      if (kind === "backend") {
        const wasUp = this.state.backend.state === "up";
        const msg = [
          `${label} exited code=${code ?? "null"} signal=${signal ?? "null"}`,
          lastStderr ? `stderr:\n${lastStderr}` : "",
        ]
          .filter(Boolean)
          .join("\n");
        this.failBackend(win, msg, wasUp ? "后端已退出" : "后端启动失败");
        return;
      }
      if (this.state.connect.state !== "starting") return;
      this.degradeConnect(
        win,
        `[${label}:${gen}] exited code=${code ?? "null"} signal=${
          signal ?? "null"
        }`,
      );
    });
  }
}

export const sidecar = new SidecarManager();
