/** Strip browser security headers so embedded pages and iframes are unrestricted. */
const RESTRICTIVE_HEADER_NAMES = new Set([
  "content-security-policy",
  "content-security-policy-report-only",
  "x-content-security-policy",
  "x-webkit-csp",
  "x-frame-options",
  "cross-origin-opener-policy",
  "cross-origin-embedder-policy",
  "cross-origin-resource-policy",
  "permissions-policy",
  "feature-policy",
]);

export function relaxResponseHeaders(
  responseHeaders: Record<string, string[] | undefined> | undefined,
): Record<string, string[]> {
  if (!responseHeaders) return {};
  const next: Record<string, string[]> = {};
  for (const [key, values] of Object.entries(responseHeaders)) {
    if (RESTRICTIVE_HEADER_NAMES.has(key.toLowerCase())) continue;
    if (values) next[key] = values;
  }
  return next;
}
