import { join } from "node:path";
import { randomUUID } from "node:crypto";
import { app, utilityProcess, type UtilityProcess } from "electron";
import type { GuestBrowserHistoryItem } from "@qiwork/desktop-runtime/bridge";
import { historyUtilityPath } from "./paths";

type Pending = {
  resolve: (value: unknown) => void;
  reject: (error: Error) => void;
  generation: number;
};

class GuestHistoryClient {
  private process: UtilityProcess | null = null;
  private generation = 0;
  private pending = new Map<string, Pending>();
  private opened = false;

  async recent(limit = 100): Promise<GuestBrowserHistoryItem[]> {
    await this.ensure();
    return (await this.call("recent", { limit })) as GuestBrowserHistoryItem[];
  }

  async record(item: {
    url: string;
    title?: string;
    favicon?: string;
    visitedAt?: number;
  }): Promise<void> {
    await this.ensure();
    await this.call("record", item);
  }

  async clear(): Promise<void> {
    await this.ensure();
    await this.call("clear");
  }

  async clearBefore(before: number): Promise<void> {
    await this.ensure();
    await this.call("clearBefore", { before });
  }

  async query(text?: string, limit = 500): Promise<GuestBrowserHistoryItem[]> {
    await this.ensure();
    return (await this.call("query", { text, limit })) as GuestBrowserHistoryItem[];
  }

  async remove(urls: string[]): Promise<void> {
    await this.ensure();
    await this.call("remove", { urls });
  }

  shutdown(): void {
    this.rejectAll(new Error("history utility stopped"));
    try {
      this.process?.kill();
    } catch {
      /* ignore */
    }
    this.process = null;
    this.opened = false;
  }

  private async ensure(): Promise<void> {
    const proc = this.ensureProcess();
    if (this.opened) return;
    const databasePath = join(app.getPath("userData"), "guest-browser", "history.sqlite");
    await this.call("open", { databasePath });
    if (this.process === proc) this.opened = true;
  }

  private ensureProcess(): UtilityProcess {
    if (this.process?.pid) return this.process;
    const generation = ++this.generation;
    const proc = utilityProcess.fork(historyUtilityPath(), [], {
      serviceName: "QIWork Browser History",
      stdio: "pipe",
    });
    this.process = proc;
    this.opened = false;
    proc.on("message", (message) => {
      if (!message || typeof message !== "object") return;
      const response = message as {
        id?: string;
        generation?: number;
        ok?: boolean;
        result?: unknown;
        error?: string;
      };
      if (typeof response.id !== "string" || response.generation !== generation) return;
      const pending = this.pending.get(response.id);
      if (!pending) return;
      this.pending.delete(response.id);
      if (response.ok) pending.resolve(response.result);
      else pending.reject(new Error(response.error || "history utility failed"));
    });
    proc.on("exit", () => {
      if (this.process === proc) {
        this.process = null;
        this.opened = false;
        this.rejectGeneration(generation, new Error("history utility exited"));
      }
    });
    return proc;
  }

  private call(type: string, payload?: unknown): Promise<unknown> {
    const proc = this.ensureProcess();
    const id = randomUUID();
    const generation = this.generation;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject, generation });
      proc.postMessage({ id, generation, type, payload });
    });
  }

  private rejectGeneration(generation: number, error: Error): void {
    for (const [id, pending] of this.pending) {
      if (pending.generation === generation) {
        this.pending.delete(id);
        pending.reject(error);
      }
    }
  }

  private rejectAll(error: Error): void {
    for (const pending of this.pending.values()) pending.reject(error);
    this.pending.clear();
  }
}

export const guestHistory = new GuestHistoryClient();
