import { randomBytes } from "node:crypto";
import http from "node:http";
import { URL } from "node:url";
import { BrowserWindow, session, type Session } from "electron";
import { IpcListen } from "@qiwork/desktop-runtime/ipcEvents";
import { showDesktopNotification } from "./notifications";

const AUTH_HEADER = "x-qiwork-desktop-host-token";
const EVENT_POLL_MS = 20_000;

type WindowEventType = "navigated" | "closed";

type WindowEvent = {
  seq: number;
  type: WindowEventType;
  url?: string;
};

type LoginEntry = {
  win: BrowserWindow;
  session: Session;
  events: WindowEvent[];
  nextSeq: number;
  waiters: Array<(events: WindowEvent[]) => void>;
};

export type PlatformLoginHostEnv = {
  QIWORK_DESKTOP_HOST: string;
  QIWORK_DESKTOP_HOST_TOKEN: string;
};

export class PlatformLoginHost {
  private server: http.Server | null = null;
  private token = "";
  private baseUrl = "";
  private readonly windows = new Map<string, LoginEntry>();
  private mainWindow: BrowserWindow | null = null;

  async start(mainWindow: BrowserWindow): Promise<PlatformLoginHostEnv> {
    if (this.server) {
      return this.getEnv()!;
    }
    this.mainWindow = mainWindow;
    this.token = randomBytes(32).toString("hex");

    await new Promise<void>((resolve, reject) => {
      const server = http.createServer((req, res) => {
        void this.handle(req, res);
      });
      server.once("error", reject);
      server.listen(0, "127.0.0.1", () => {
        const addr = server.address();
        if (!addr || typeof addr === "string") {
          reject(new Error("platform login host: failed to bind loopback"));
          return;
        }
        this.baseUrl = `http://127.0.0.1:${addr.port}`;
        this.server = server;
        resolve();
      });
    });

    return this.getEnv()!;
  }

  getEnv(): PlatformLoginHostEnv | null {
    if (!this.baseUrl || !this.token) return null;
    return {
      QIWORK_DESKTOP_HOST: this.baseUrl,
      QIWORK_DESKTOP_HOST_TOKEN: this.token,
    };
  }

  stop(): void {
    for (const entry of this.windows.values()) {
      if (!entry.win.isDestroyed()) {
        entry.win.close();
      }
    }
    this.windows.clear();
    if (this.server) {
      this.server.close();
      this.server = null;
    }
    this.baseUrl = "";
    this.token = "";
    this.mainWindow = null;
  }

  private authorized(req: http.IncomingMessage): boolean {
    const header = req.headers[AUTH_HEADER];
    const token = Array.isArray(header) ? header[0] : header;
    return token === this.token;
  }

  private writeJson(
    res: http.ServerResponse,
    status: number,
    body: unknown,
  ): void {
    res.writeHead(status, { "Content-Type": "application/json; charset=utf-8" });
    res.end(JSON.stringify(body));
  }

  private async readJson(req: http.IncomingMessage): Promise<Record<string, unknown>> {
    const chunks: Buffer[] = [];
    for await (const chunk of req) {
      chunks.push(chunk as Buffer);
    }
    const text = Buffer.concat(chunks).toString("utf8").trim();
    if (!text) return {};
    return JSON.parse(text) as Record<string, unknown>;
  }

  private entryFor(id: string): LoginEntry | null {
    const entry = this.windows.get(id);
    if (!entry || entry.win.isDestroyed()) {
      this.windows.delete(id);
      return null;
    }
    return entry;
  }

  private pushEvent(entry: LoginEntry, type: WindowEventType, url?: string): void {
    const event: WindowEvent = {
      seq: entry.nextSeq++,
      type,
      ...(url ? { url } : {}),
    };
    entry.events.push(event);
    const waiters = entry.waiters.splice(0);
    for (const wake of waiters) {
      wake(entry.events);
    }
  }

  private eventsAfter(entry: LoginEntry, after: number): WindowEvent[] {
    return entry.events.filter((event) => event.seq > after);
  }

  private waitForEvents(
    entry: LoginEntry,
    after: number,
  ): Promise<WindowEvent[]> {
    const pending = this.eventsAfter(entry, after);
    if (pending.length > 0) {
      return Promise.resolve(pending);
    }
    return new Promise((resolve) => {
      const timer = setTimeout(() => {
        entry.waiters = entry.waiters.filter((wake) => wake !== onEvents);
        resolve([]);
      }, EVENT_POLL_MS);
      const onEvents = (events: WindowEvent[]) => {
        const next = events.filter((event) => event.seq > after);
        if (next.length === 0) return;
        clearTimeout(timer);
        entry.waiters = entry.waiters.filter((wake) => wake !== onEvents);
        resolve(next);
      };
      entry.waiters.push(onEvents);
    });
  }

  private bindWindowEvents(id: string, entry: LoginEntry): void {
    const contents = entry.win.webContents;
    const onNavigate = (_event: unknown, url: string) => {
      this.pushEvent(entry, "navigated", url);
    };
    contents.on("did-navigate", onNavigate);
    contents.on("did-navigate-in-page", onNavigate);
    entry.win.on("closed", () => {
      this.pushEvent(entry, "closed");
      this.windows.delete(id);
      void entry.session.clearStorageData();
      void entry.session.clearCache();
    });
  }

  private forwardUiEvent(payload: Record<string, unknown>): void {
    const win = this.mainWindow;
    if (!win || win.isDestroyed()) return;
    win.webContents.send(IpcListen.platformLoginEvent, payload);
    if (String(payload.phase ?? "") === "ready") {
      const platformName =
        typeof payload.platform_name === "string"
          ? payload.platform_name
          : String(payload.platform ?? "");
      showDesktopNotification(
        "平台登录成功",
        platformName ? `${platformName} 已连接` : "账号已连接",
      );
    }
  }

  private async handle(
    req: http.IncomingMessage,
    res: http.ServerResponse,
  ): Promise<void> {
    if (!this.authorized(req)) {
      this.writeJson(res, 401, { error: "unauthorized" });
      return;
    }

    const url = new URL(req.url ?? "/", this.baseUrl || "http://127.0.0.1");
    const method = req.method ?? "GET";
    const path = url.pathname;

    try {
      if (method === "POST" && path === "/login-windows") {
        const body = await this.readJson(req);
        const title = String(body.title ?? "登录");
        const startUrl = String(body.url ?? "").trim();
        if (!startUrl) {
          this.writeJson(res, 400, { error: "url required" });
          return;
        }

        const id = randomBytes(16).toString("hex");
        const partition = `qiwork-platform-login-${id}`;
        const loginSession = session.fromPartition(partition, { cache: false });
        const win = new BrowserWindow({
          width: 1024,
          height: 720,
          title,
          parent: this.mainWindow ?? undefined,
          show: true,
          autoHideMenuBar: true,
          webPreferences: {
            session: loginSession,
            contextIsolation: true,
            nodeIntegration: false,
            sandbox: true,
          },
        });

        win.webContents.setWindowOpenHandler(({ url: target }) => {
          if (target) {
            void win.loadURL(target);
          }
          return { action: "deny" };
        });

        const entry: LoginEntry = {
          win,
          session: loginSession,
          events: [],
          nextSeq: 1,
          waiters: [],
        };
        this.windows.set(id, entry);
        this.bindWindowEvents(id, entry);

        await win.loadURL(startUrl);
        this.writeJson(res, 200, { id });
        return;
      }

      if (method === "POST" && path === "/ui-events") {
        const body = await this.readJson(req);
        this.forwardUiEvent(body);
        this.writeJson(res, 200, { ok: true });
        return;
      }

      const windowMatch = path.match(/^\/login-windows\/([^/]+)$/);
      if (windowMatch && method === "GET") {
        const entry = this.entryFor(windowMatch[1]);
        if (!entry) {
          this.writeJson(res, 404, { error: "not found" });
          return;
        }
        this.writeJson(res, 200, {
          open: true,
          url: entry.win.webContents.getURL(),
        });
        return;
      }

      const eventsMatch = path.match(/^\/login-windows\/([^/]+)\/events$/);
      if (eventsMatch && method === "GET") {
        const entry = this.entryFor(eventsMatch[1]);
        if (!entry) {
          this.writeJson(res, 404, { error: "not found" });
          return;
        }
        const after = Number.parseInt(url.searchParams.get("after") ?? "0", 10);
        const events = await this.waitForEvents(entry, Number.isFinite(after) ? after : 0);
        this.writeJson(res, 200, { events });
        return;
      }

      const cookiesMatch = path.match(/^\/login-windows\/([^/]+)\/cookies$/);
      if (cookiesMatch && method === "GET") {
        const entry = this.entryFor(cookiesMatch[1]);
        if (!entry) {
          this.writeJson(res, 404, { error: "not found" });
          return;
        }
        const cookies = await entry.session.cookies.get({});
        const jar: Record<string, string> = {};
        for (const cookie of cookies) {
          if (cookie.name && cookie.value) {
            jar[cookie.name] = cookie.value;
          }
        }
        this.writeJson(res, 200, { cookies: jar });
        return;
      }

      const navigateMatch = path.match(/^\/login-windows\/([^/]+)\/navigate$/);
      if (navigateMatch && method === "POST") {
        const entry = this.entryFor(navigateMatch[1]);
        if (!entry) {
          this.writeJson(res, 404, { error: "not found" });
          return;
        }
        const body = await this.readJson(req);
        const target = String(body.url ?? "").trim();
        if (!target) {
          this.writeJson(res, 400, { error: "url required" });
          return;
        }
        await entry.win.loadURL(target);
        this.writeJson(res, 200, { ok: true });
        return;
      }

      const deleteMatch = path.match(/^\/login-windows\/([^/]+)$/);
      if (deleteMatch && method === "DELETE") {
        const id = deleteMatch[1];
        const entry = this.entryFor(id);
        if (!entry) {
          this.writeJson(res, 404, { error: "not found" });
          return;
        }
        entry.win.close();
        this.windows.delete(id);
        this.writeJson(res, 200, { ok: true });
        return;
      }

      this.writeJson(res, 404, { error: "not found" });
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      this.writeJson(res, 500, { error: message });
    }
  }
}

export const platformLoginHost = new PlatformLoginHost();
