import { powerSaveBlocker } from "electron";

let blockerId: number | null = null;

/** Returns whether prevention is active after the call. */
export function setIdleSleepPrevention(enabled: boolean): boolean {
  if (enabled) {
    if (blockerId === null) {
      blockerId = powerSaveBlocker.start("prevent-app-suspension");
    }
    return powerSaveBlocker.isStarted(blockerId);
  }
  if (blockerId !== null) {
    powerSaveBlocker.stop(blockerId);
    blockerId = null;
  }
  return false;
}

export function releaseIdleSleep(): void {
  setIdleSleepPrevention(false);
}
