import { BrowserWindow, ipcMain, type WebContents } from "electron";
import {
  parseUpdatePromptAction,
  type UpdatePromptPayload,
} from "@qiwork/desktop-runtime/bridge";
import { IpcListen } from "@qiwork/desktop-runtime/ipcEvents";
import { updatePromptPageUrl, updatePromptPreloadPath } from "./paths";
import { updatePromptWindowBounds } from "./update-prompt-layout";

const DATA = "update-prompt:data";
const ACTION = "update-prompt:action";
const RESIZE = "update-prompt:resize";

/** Sibling HUD window sized to the card so it can sit above WebContentsView. */
export class UpdatePromptWindow {
  private win: BrowserWindow | null = null;
  private host: BrowserWindow | null = null;
  private requester: WebContents | null = null;
  private wanted = false;
  private loaded = false;
  private data: UpdatePromptPayload | null = null;
  private size = { w: 432, h: 220 };
  private hostOffs: Array<() => void> = [];

  constructor() {
    ipcMain.on(ACTION, (event, payload) => {
      if (!this.isOwnSender(event.sender)) return;
      this.forwardAction(payload);
    });
    ipcMain.on(RESIZE, (event, payload) => {
      if (!this.isOwnSender(event.sender)) return;
      const next = readSize(payload);
      if (!next) return;
      this.size = next;
      this.reposition();
      this.showIfActive();
    });
  }

  set(payload: UpdatePromptPayload, requester: WebContents): void {
    if (!payload.open) {
      this.hide();
      return;
    }
    this.show(payload, requester);
  }

  hide(): void {
    this.wanted = false;
    this.data = null;
    this.destroyWin();
  }

  destroy(): void {
    this.detachHostListeners();
    this.requester = null;
    this.host = null;
    this.hide();
  }

  private show(payload: UpdatePromptPayload, requester: WebContents): void {
    this.wanted = true;
    this.requester = requester;
    this.data = payload;
    this.bindHost(BrowserWindow.fromWebContents(requester));
    const existing = this.aliveWin();
    if (!existing) {
      this.create();
      return;
    }
    if (this.loaded) existing.webContents.send(DATA, this.data);
    this.showIfActive();
  }

  private create(): void {
    this.loaded = false;
    const win = new BrowserWindow({
      width: this.size.w,
      height: this.size.h,
      transparent: true,
      frame: false,
      resizable: false,
      movable: false,
      alwaysOnTop: true,
      skipTaskbar: true,
      hasShadow: false,
      focusable: false,
      show: false,
      webPreferences: {
        contextIsolation: true,
        nodeIntegration: false,
        sandbox: true,
        preload: updatePromptPreloadPath(),
      },
    });
    win.setAlwaysOnTop(true, "pop-up-menu");
    void win.loadURL(updatePromptPageUrl());
    win.webContents.once("did-finish-load", () => {
      if (this.win !== win) return;
      this.loaded = true;
      if (this.data) win.webContents.send(DATA, this.data);
    });
    win.on("closed", () => {
      if (this.win === win) {
        this.win = null;
        this.loaded = false;
      }
    });
    this.win = win;
  }

  private reposition(): void {
    const win = this.aliveWin();
    const host = this.aliveHost();
    if (!win || !host) return;
    win.setBounds(updatePromptWindowBounds(host.getContentBounds(), this.size));
  }

  private showIfActive(): void {
    const win = this.aliveWin();
    const host = this.aliveHost();
    if (!this.wanted || !win || !host) return;
    if (host.isMinimized() || !host.isVisible() || !host.isFocused()) {
      if (win.isVisible()) win.hide();
      return;
    }
    this.reposition();
    if (!win.isVisible()) win.showInactive();
  }

  private forwardAction(raw: unknown): void {
    const type = parseUpdatePromptAction(raw);
    if (!type || !this.requester || this.requester.isDestroyed()) return;
    this.requester.send(IpcListen.updatePromptAction, { type });
  }

  private bindHost(host: BrowserWindow | null): void {
    if (!host || host.isDestroyed()) return;
    if (host === this.host && this.hostOffs.length) return;
    this.detachHostListeners();
    this.host = host;
    this.attachHostListeners();
  }

  private attachHostListeners(): void {
    const host = this.aliveHost();
    if (!host) return;
    const onMove = () => this.reposition();
    const onResize = () => {
      this.reposition();
      this.showIfActive();
    };
    const onHide = () => {
      const win = this.aliveWin();
      if (win?.isVisible()) win.hide();
    };
    const onShow = () => this.showIfActive();
    host.on("move", onMove);
    host.on("resize", onResize);
    host.on("minimize", onHide);
    host.on("hide", onHide);
    host.on("blur", onHide);
    host.on("restore", onShow);
    host.on("show", onShow);
    host.on("focus", onShow);
    host.on("enter-full-screen", onResize);
    host.on("leave-full-screen", onResize);
    host.on("closed", onHide);
    this.hostOffs = [
      () => host.off("move", onMove),
      () => host.off("resize", onResize),
      () => host.off("minimize", onHide),
      () => host.off("hide", onHide),
      () => host.off("blur", onHide),
      () => host.off("restore", onShow),
      () => host.off("show", onShow),
      () => host.off("focus", onShow),
      () => host.off("enter-full-screen", onResize),
      () => host.off("leave-full-screen", onResize),
      () => host.off("closed", onHide),
    ];
  }

  private detachHostListeners(): void {
    for (const off of this.hostOffs) off();
    this.hostOffs = [];
  }

  private destroyWin(): void {
    this.loaded = false;
    const win = this.aliveWin();
    if (win) win.close();
    this.win = null;
  }

  private isOwnSender(sender: WebContents): boolean {
    const win = this.aliveWin();
    return Boolean(win && sender === win.webContents);
  }

  private aliveWin(): BrowserWindow | null {
    return this.win && !this.win.isDestroyed() ? this.win : null;
  }

  private aliveHost(): BrowserWindow | null {
    return this.host && !this.host.isDestroyed() ? this.host : null;
  }
}

function readSize(raw: unknown): { w: number; h: number } | null {
  if (!raw || typeof raw !== "object") return null;
  const rec = raw as { width?: unknown; height?: unknown };
  const width = Number(rec.width);
  const height = Number(rec.height);
  if (!Number.isFinite(width) || !Number.isFinite(height)) return null;
  return { w: Math.max(1, Math.round(width)), h: Math.max(1, Math.round(height)) };
}

let instance: UpdatePromptWindow | null = null;

export function getUpdatePromptWindow(): UpdatePromptWindow {
  if (!instance) instance = new UpdatePromptWindow();
  return instance;
}
