import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { dialog, shell } from "electron";
import { sidecar } from "./sidecar";

const execFileAsync = promisify(execFile);

const SUPPORTED_EXTERNAL_PREFIXES = ["http:", "https:", "mailto:", "tel:"];

export async function allowBackendForeground(): Promise<void> {
  if (process.platform !== "win32") return;
  const pid = sidecar.getGatewayPid();
  if (!pid) return;
  const ps = `
Add-Type @"
using System;
using System.Runtime.InteropServices;
public class Fg {
  [DllImport("user32.dll")] public static extern bool AllowSetForegroundWindow(int dwProcessId);
}
"@
[Fg]::AllowSetForegroundWindow(${pid})
`;
  try {
    await execFileAsync("powershell", ["-NoProfile", "-Command", ps], {
      windowsHide: true,
    });
  } catch (err) {
    console.warn("[shell] allowBackendForeground failed", err);
  }
}

export async function openFolder(folderPath: string): Promise<void> {
  await shell.openPath(folderPath);
}

export async function openFile(filePath: string): Promise<void> {
  await shell.openPath(filePath);
}

export async function openExternalLink(url: string): Promise<void> {
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    throw new Error("unsupported protocol");
  }
  if (!SUPPORTED_EXTERNAL_PREFIXES.includes(parsed.protocol)) {
    throw new Error("unsupported protocol");
  }
  await shell.openExternal(url);
}

export async function showOpenDialog(options?: {
  directory?: boolean;
  title?: string;
}): Promise<string | null> {
  const result = await dialog.showOpenDialog({
    title: options?.title,
    properties: options?.directory
      ? ["openDirectory"]
      : ["openFile"],
  });
  if (result.canceled || result.filePaths.length === 0) return null;
  return result.filePaths[0] ?? null;
}

export async function showSaveDialog(options?: {
  defaultPath?: string;
  title?: string;
}): Promise<string | null> {
  const result = await dialog.showSaveDialog({
    title: options?.title,
    defaultPath: options?.defaultPath,
  });
  if (result.canceled || !result.filePath) return null;
  return result.filePath;
}
