import { createWriteStream } from "node:fs";
import { mkdir, stat } from "node:fs/promises";
import path from "node:path";
import { pipeline } from "node:stream/promises";
import { Readable } from "node:stream";
import { net } from "electron";

function assertLocalBackendUrl(raw: string): URL {
  let parsed: URL;
  try {
    parsed = new URL(raw);
  } catch {
    throw new Error("invalid download URL");
  }
  if (parsed.protocol !== "http:") {
    throw new Error("download URL protocol is not supported");
  }
  const host = parsed.hostname.toLowerCase();
  if (host !== "localhost" && host !== "127.0.0.1" && host !== "::1") {
    throw new Error("download URL must target the local backend");
  }
  return parsed;
}

/** Stream a loopback backend response to a user-chosen path (no system proxy). */
export async function downloadBackendFile(request: {
  url: string;
  filePath: string;
  headers?: Record<string, string>;
}): Promise<void> {
  const url = assertLocalBackendUrl(request.url);
  const filePath = request.filePath.trim();
  if (!filePath) throw new Error("download file path is empty");

  const parentDir = path.dirname(filePath);
  // Drive roots (`D:\`) and UNC shares already exist but reject mkdir with
  // EPERM, so only create the directory when it is genuinely missing.
  try {
    await stat(parentDir);
  } catch {
    await mkdir(parentDir, { recursive: true });
  }

  const headers = new Headers(request.headers ?? {});
  const response = await net.fetch(url.toString(), {
    method: "GET",
    headers,
  });
  if (!response.ok) {
    throw new Error(`download request failed with status code ${response.status}`);
  }
  if (!response.body) {
    throw new Error("download response has no body");
  }

  const nodeStream = Readable.fromWeb(
    response.body as import("node:stream/web").ReadableStream,
  );
  await pipeline(nodeStream, createWriteStream(filePath));
}
