export const UPDATE_PROMPT_ANCHOR_RIGHT = 20;
export const UPDATE_PROMPT_ANCHOR_BOTTOM = 20;
export const UPDATE_PROMPT_SHADOW_PAD = 36;

export function updatePromptWindowBounds(
  host: { x: number; y: number; width: number; height: number },
  size: { w: number; h: number },
): { x: number; y: number; width: number; height: number } {
  return {
    x: Math.round(
      host.x + host.width - UPDATE_PROMPT_ANCHOR_RIGHT + UPDATE_PROMPT_SHADOW_PAD - size.w,
    ),
    y: Math.round(
      host.y + host.height - UPDATE_PROMPT_ANCHOR_BOTTOM + UPDATE_PROMPT_SHADOW_PAD - size.h,
    ),
    width: size.w,
    height: size.h,
  };
}
