import { existsSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { join } from "node:path";

export const MEIFANNAO_CATALOG_URL =
  "https://www.meifannao.cn/myApi/api/pc/browser_list";
export const MEIFANNAO_EXTENSION_ID = "meifannao";

export type GuestExtensionPack = {
  url: string;
  version: string;
};

type CatalogItem = {
  downUrl?: unknown;
  version?: unknown;
  browername?: unknown;
};

export function pickMeifannaoPack(payload: unknown): GuestExtensionPack | null {
  if (!payload || typeof payload !== "object") return null;
  const data = (payload as { data?: { downlist?: unknown } }).data;
  if (!data || !Array.isArray(data.downlist)) return null;
  const items = data.downlist.filter(
    (item): item is CatalogItem => Boolean(item) && typeof item === "object",
  );
  const preferred =
    items.find((item) => String(item.browername ?? "") === "Chrome") ?? items[0];
  if (!preferred) return null;
  const url = String(preferred.downUrl ?? "").trim();
  if (!url.startsWith("https://")) return null;
  const version = String(preferred.version ?? "").trim() || "0";
  return { url, version };
}

export function safeZipEntryPath(name: string): string | null {
  const rel = name.replace(/\\/g, "/").replace(/^\/+/, "");
  if (!rel || rel.endsWith("/")) return null;
  const parts = rel.split("/").filter((part) => part && part !== ".");
  if (parts.some((part) => part === "..")) return null;
  return parts.join("/");
}

const ELECTRON_DROP_PERMISSIONS = new Set(["webNavigation"]);

/** Electron has no chrome.webNavigation, and local storage is 10MB unless unlimited. */
export function adaptGuestExtensionManifest(dir: string): boolean {
  const file = join(dir, "manifest.json");
  if (!existsSync(file)) return false;
  let manifest: { permissions?: unknown };
  try {
    manifest = JSON.parse(readFileSync(file, "utf8")) as { permissions?: unknown };
  } catch {
    return false;
  }
  const current = Array.isArray(manifest.permissions)
    ? manifest.permissions.filter((item): item is string => typeof item === "string")
    : [];
  const next = current.filter((item) => !ELECTRON_DROP_PERMISSIONS.has(item));
  if (!next.includes("unlimitedStorage")) next.push("unlimitedStorage");
  if (next.length === current.length && next.every((item, i) => item === current[i])) {
    return false;
  }
  manifest.permissions = next;
  writeFileSync(file, JSON.stringify(manifest));
  return true;
}

export function findExtensionRoot(dir: string): string | null {
  if (!existsSync(dir) || !statSync(dir).isDirectory()) return null;
  if (existsSync(join(dir, "manifest.json"))) return dir;
  for (const name of readdirSync(dir)) {
    const child = join(dir, name);
    if (statSync(child).isDirectory() && existsSync(join(child, "manifest.json"))) {
      return child;
    }
  }
  return null;
}
