/**
 * Semantic desktop host API. Frontend and helpers call this — never window.electronAPI.
 */
import type { DesktopRuntimeState } from "./runtimeState";
import type { DesktopUpdaterEvent } from "./updaterEvent";

export interface DesktopRuntimeVersions {
  electron: string;
  chrome: string;
  node: string;
  v8: string;
  arch: string;
}

export interface DesktopBridge {
  getRuntimeState(): Promise<DesktopRuntimeState>;
  restartBackend(): Promise<void>;
  onRuntimeState(cb: (state: DesktopRuntimeState) => void): () => void;
  openExternalLink(url: string): Promise<void>;
  openFolder(path: string): Promise<void>;
  openFile(path: string): Promise<void>;
  allowBackendForeground(): Promise<void>;
  setIdleSleepPrevention(enabled: boolean): Promise<boolean>;
  getUiLanguage(): Promise<string | null>;
  setUiLanguage(lang: string): Promise<void>;
  minimize(): Promise<void>;
  toggleMaximize(): Promise<void>;
  closeWindow(): Promise<void>;
  openDevTools(): Promise<void>;
  showOpenDialog(options?: {
    directory?: boolean;
    title?: string;
  }): Promise<string | null>;
  showSaveDialog(options?: {
    defaultPath?: string;
    title?: string;
  }): Promise<string | null>;
  downloadBackendFile(request: {
    url: string;
    filePath: string;
    headers?: Record<string, string>;
  }): Promise<void>;
  getAppVersion(): Promise<string>;
  getRuntimeVersions(): Promise<DesktopRuntimeVersions>;
  checkForUpdates(): Promise<void>;
  downloadUpdate(): Promise<void>;
  quitAndInstall(): Promise<void>;
  onUpdater(cb: (event: DesktopUpdaterEvent) => void): () => void;
  onPlatformLoginEvent(cb: (payload: Record<string, unknown>) => void): () => void;
  onAuthDeviceComplete(cb: () => void): () => void;
  onDeepLinkNavigate(
    cb: (payload: { path: string; search?: string }) => void,
  ): () => void;
  showNotification(payload: { title: string; body: string }): Promise<void>;
  writeClipboardText(text: string): Promise<void>;
  showGuestBrowser(args: {
    bounds: { x: number; y: number; width: number; height: number };
  }): Promise<GuestBrowserState>;
  hideGuestBrowser(): Promise<void>;
  setGuestBrowserBounds(bounds: {
    x: number;
    y: number;
    width: number;
    height: number;
  }): Promise<void>;
  getGuestBrowserState(): Promise<GuestBrowserState>;
  guestBrowserNewTab(url?: string): Promise<GuestBrowserState>;
  guestBrowserCloseTab(id: string): Promise<GuestBrowserState>;
  guestBrowserSwitchTab(id: string): Promise<GuestBrowserState>;
  guestBrowserNavigate(url: string): Promise<GuestBrowserState>;
  guestBrowserBack(): Promise<GuestBrowserState>;
  guestBrowserForward(): Promise<GuestBrowserState>;
  guestBrowserReload(): Promise<GuestBrowserState>;
  guestBrowserHome(): Promise<GuestBrowserState>;
  guestBrowserStop(): Promise<GuestBrowserState>;
  guestBrowserCommand(cmd: GuestBrowserCommand): Promise<GuestBrowserState>;
  guestBrowserOverlayReady(): Promise<void>;
  onGuestBrowserState(cb: (state: GuestBrowserState) => void): () => void;
  onGuestBrowserOverlay(
    cb: (shot: GuestBrowserOverlaySnapshot | null) => void,
  ): () => void;
  setUpdatePrompt(payload: UpdatePromptPayload): Promise<void>;
  onUpdatePromptAction(cb: (action: UpdatePromptAction) => void): () => void;
  platform: "darwin" | "win32" | "linux" | "unknown";
}

export type GuestBrowserOverlayLayer = {
  dataUrl: string;
  x: number;
  y: number;
  width: number;
  height: number;
};

export type GuestBrowserOverlaySnapshot = {
  width: number;
  height: number;
  layers: GuestBrowserOverlayLayer[];
};

export type GuestBrowserGroupColor =
  | "blue"
  | "red"
  | "orange"
  | "yellow"
  | "green"
  | "cyan"
  | "purple"
  | "pink"
  | "grey";

export type GuestBrowserGroup = {
  id: string;
  name: string;
  color: GuestBrowserGroupColor;
  collapsed: boolean;
};

export type GuestBrowserTab = {
  id: string;
  title: string;
  url: string;
  favicon: string;
  insecure: boolean;
  loading: boolean;
  canGoBack: boolean;
  canGoForward: boolean;
  pinned: boolean;
  groupId: string | null;
};

export type GuestBrowserHistoryItem = {
  id: string;
  title: string;
  url: string;
  favicon: string;
  visitedAt: number;
};

export type GuestBrowserDownload = {
  id: string;
  filename: string;
  url: string;
  path: string;
  state:
    | "awaiting-permission"
    | "progressing"
    | "paused"
    | "completed"
    | "cancelled"
    | "interrupted"
    | "blocked";
  received: number;
  total: number;
  startedAt: number;
  sourcePageDomain: string;
};

export type GuestBrowserClosedEntry = {
  id: string;
  kind: "tab" | "group";
  title: string;
  url?: string;
  color?: GuestBrowserGroupColor;
};

export type GuestBrowserCommand =
  | { op: "dragTab"; tabId: string; beforeId: string | null; groupId?: string | null }
  | { op: "setPinned"; id: string; pinned: boolean }
  | {
      op: "group";
      action: "create" | "add" | "remove" | "update" | "close" | "ungroup";
      tabId?: string;
      groupId?: string;
      patch?: Partial<Pick<GuestBrowserGroup, "name" | "color" | "collapsed">>;
    }
  | { op: "reopenClosed"; entryId?: string }
  | { op: "closeOthers"; id: string }
  | { op: "closeRight"; id: string }
  | { op: "duplicate"; id: string }
  | { op: "removeHistory"; ids: string[] }
  | { op: "openDownload"; id: string }
  | { op: "revealDownload"; id: string }
  | { op: "cancelDownload"; id: string }
  | { op: "pauseDownload"; id: string }
  | { op: "resumeDownload"; id: string }
  | { op: "removeDownload"; id: string }
  | { op: "clearFinishedDownloads" }
  | { op: "chooseDownloadDirectory" }
  | { op: "setDownloadDirectory"; path: string }
  | { op: "openDownloadDirectory" }
  | { op: "allowDownload"; id: string }
  | { op: "denyDownload"; id: string }
  | { op: "setAskWhereToSave"; value: boolean }
  | { op: "setShowWhenComplete"; value: boolean }
  | { op: "setChromeHeight"; height: number }
  | { op: "setPanel"; panel: "history" | "downloads" }
  | { op: "openShortcut"; redirect: string }
  | { op: "openBrowser" }
  | { op: "openExtensionPopup"; id: string; x?: number; y?: number; width?: number }
  | { op: "setOverlayOpen"; open: boolean }
  | { op: "setHostOverlay"; open: boolean }
  | { op: "applyTheme"; themeMode: "light" | "dark" | "system"; isDark: boolean }
  | { op: "prefetchHostOverlay" }
  | { op: "setBarVisible"; value: boolean }
  | { op: "setDoubleClickCloseTab"; value: boolean }
  | { op: "setHardwareAcceleration"; value: boolean }
  | { op: "restartForHardwareAcceleration" }
  | { op: "setZoom"; dir: "in" | "out" }
  | { op: "toggleFullscreen" }
  | { op: "toggleBookmark"; url: string; title: string }
  | { op: "updateBookmark"; id: string; title?: string; url?: string }
  | { op: "removeBookmark"; id: string }
  | { op: "setBookmarks"; bookmarks: GuestBrowserBookmark[] }
  | { op: "importBookmarksHtml" }
  | { op: "importBrowserData"; sourceId?: string }
  | {
      op: "clearData";
      cache: boolean;
      cookies: boolean;
      history: boolean;
      timeRange: GuestBrowserClearRange;
      cookieScope?: "all" | "site";
    }
  | { op: "allowCert"; host: string; url: string }
  | { op: "denyCert" };

export const UPDATE_PROMPT_ACTIONS = [
  "dismiss",
  "download",
  "retry",
  "install",
  "changelog",
] as const;

export type UpdatePromptAction = (typeof UPDATE_PROMPT_ACTIONS)[number];

export type UpdatePromptPayload = {
  open: boolean;
  step: string;
  latestVersion: string;
  downloaded: number;
  total: number;
  error: string;
};

export function isUpdatePromptAction(value: unknown): value is UpdatePromptAction {
  return (
    typeof value === "string" &&
    (UPDATE_PROMPT_ACTIONS as readonly string[]).includes(value)
  );
}

export function parseUpdatePromptAction(raw: unknown): UpdatePromptAction | null {
  if (!raw || typeof raw !== "object" || !("type" in raw)) return null;
  const type = (raw as { type: unknown }).type;
  return isUpdatePromptAction(type) ? type : null;
}

export function parseUpdatePromptPayload(raw: unknown): UpdatePromptPayload | null {
  if (!raw || typeof raw !== "object") return null;
  const rec = raw as Record<string, unknown>;
  if (typeof rec.open !== "boolean") return null;
  return {
    open: rec.open,
    step: typeof rec.step === "string" ? rec.step : "idle",
    latestVersion: typeof rec.latestVersion === "string" ? rec.latestVersion : "",
    downloaded: typeof rec.downloaded === "number" ? rec.downloaded : 0,
    total: typeof rec.total === "number" ? rec.total : 0,
    error: typeof rec.error === "string" ? rec.error : "",
  };
}

export type GuestBrowserClearRange =
  | "last-15min"
  | "last-hour"
  | "last-24h"
  | "last-7d"
  | "last-4w"
  | "all";

export type GuestBrowserBookmark = {
  id: string;
  title: string;
  url: string;
};

export type GuestBrowserImportSource = {
  id: string;
  name: string;
  count: number;
};

export type GuestBrowserExtension = {
  id: string;
  name: string;
  popupUrl: string;
  iconDataUrl: string;
};

export type GuestBrowserState = {
  tabs: GuestBrowserTab[];
  activeTabId: string | null;
  groups: GuestBrowserGroup[];
  history: GuestBrowserHistoryItem[];
  downloads: GuestBrowserDownload[];
  closed: GuestBrowserClosedEntry[];
  chromeHeight: number;
  askWhereToSave: boolean;
  showWhenComplete: boolean;
  downloadDirectory: string;
  downloadDirectoryAvailable: boolean;
  permission: { id: string; filename: string; url: string } | null;
  zoomPercent: number;
  doubleClickClosesTab: boolean;
  hardwareAccelerationEnabled: boolean;
  hardwareAccelerationEnabledAtLaunch: boolean;
  barVisible: boolean;
  bookmarks: GuestBrowserBookmark[];
  importSources: GuestBrowserImportSource[];
  extensions: GuestBrowserExtension[];
};

let impl: DesktopBridge | null = null;

export function registerBridge(bridge: DesktopBridge): void {
  impl = bridge;
}

export function getBridge(): DesktopBridge | null {
  return impl;
}
