import { session, type Session } from "electron";
import { applyChromeIdentity } from "./guest-chrome-identity";
import { allowGuestPermission } from "./guest-permission";
import { GUEST_PARTITIONS, isGuestPartitionName } from "./guest-profile";

const configured = new WeakSet<Session>();
const known = new Set<string>([GUEST_PARTITIONS.primary]);
const readyHooks: Array<(ses: Session) => void> = [];

export function onGuestSessionReady(hook: (ses: Session) => void): void {
  readyHooks.push(hook);
}

function installGuestPermissionPolicy(ses: Session): void {
  ses.setPermissionCheckHandler((_wc, permission, _origin, details) =>
    allowGuestPermission(permission, {
      requestingUrl: (details as { requestingUrl?: string }).requestingUrl,
    }),
  );
  ses.setPermissionRequestHandler((wc, permission, callback, details) => {
    callback(
      allowGuestPermission(permission, {
        requestingUrl:
          (details as { requestingUrl?: string }).requestingUrl || wc.getURL(),
      }),
    );
  });
}

export function ensureGuestSession(partition: string = GUEST_PARTITIONS.primary): Session {
  const ses = session.fromPartition(partition);
  if (configured.has(ses)) return ses;
  configured.add(ses);
  known.add(partition);
  applyChromeIdentity(ses);
  installGuestPermissionPolicy(ses);
  for (const hook of readyHooks) hook(ses);
  return ses;
}

export function isGuestSession(ses: Session): boolean {
  const partition = (ses as Session & { partition?: string }).partition ?? "";
  return configured.has(ses) || isGuestPartitionName(partition);
}

export function allGuestSessions(): Session[] {
  return [...known].map((partition) => ensureGuestSession(partition));
}
