import path from "node:path";
import { GUEST_PAGE_FILES } from "./renderer-schemes";

export function safeDistFile(root: string, pathname: string): string | null {
  let rel = pathname;
  try {
    rel = decodeURIComponent(pathname);
  } catch {
    return null;
  }
  rel = rel.replace(/\\/g, "/").replace(/^\/+/, "");
  if (!rel || rel.includes("\0")) return null;
  const resolved = path.resolve(root, rel);
  const relative = path.relative(root, resolved);
  if (!relative || relative.startsWith("..") || path.isAbsolute(relative)) {
    return null;
  }
  return resolved;
}

export function isGuestPageAsset(pathname: string): boolean {
  let rel = pathname;
  try {
    rel = decodeURIComponent(pathname);
  } catch {
    return false;
  }
  rel = rel.replace(/\\/g, "/").replace(/^\/+/, "");
  if ((GUEST_PAGE_FILES as readonly string[]).includes(rel)) return true;
  return rel.startsWith("assets/") && !rel.includes("..");
}
