import fs from "node:fs";
import path from "node:path";
import { app } from "electron";

const LANG_FILE = "ui-language.txt";

function configPath(): string {
  return path.join(app.getPath("userData"), LANG_FILE);
}

export function getUiLanguage(): string | null {
  try {
    const p = configPath();
    if (!fs.existsSync(p)) return null;
    const text = fs.readFileSync(p, "utf8").trim();
    return text || null;
  } catch {
    return null;
  }
}

export function setUiLanguage(language: string): void {
  const p = configPath();
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, language, "utf8");
}
