import { net, protocol, session, type Session } from "electron";
import { pathToFileURL } from "node:url";
import { safeDistFile } from "./dist-files";
import { rendererDistRoot } from "./paths";
import { HOST_APP_SCHEME } from "./renderer-schemes";

const SCHEME_PRIVILEGES = {
  standard: true,
  secure: true,
  supportFetchAPI: true,
  corsEnabled: true,
  stream: true,
} as const;

/** Register privileged host scheme (call before app ready). */
export function registerAppScheme(): void {
  protocol.registerSchemesAsPrivileged([
    { scheme: HOST_APP_SCHEME, privileges: SCHEME_PRIVILEGES },
  ]);
}

function distRoot(): string {
  return rendererDistRoot();
}

function serveHostDist(request: Request): Promise<Response> {
  const url = new URL(request.url);
  let pathname = url.pathname;
  if (pathname === "/" || pathname === "") {
    pathname = "/electron.html";
  }
  const filePath = safeDistFile(distRoot(), pathname);
  if (!filePath) {
    return Promise.resolve(new Response("Not found", { status: 404 }));
  }
  return net.fetch(pathToFileURL(filePath).toString());
}

export function attachAppProtocol(ses: Session): void {
  if (ses.protocol.isProtocolHandled(HOST_APP_SCHEME)) return;
  ses.protocol.handle(HOST_APP_SCHEME, serveHostDist);
}

export function registerAppProtocolHandler(): void {
  attachAppProtocol(session.defaultSession);
}
