function loadGuestLocation(wc: WebContents, raw: string): void {
  const kind = guestInternalKind(raw);
  if (kind) {
    loadGuestRendererPage(wc, `desktop-${kind}.html`);
    return;
  }
  if (raw) void wc.loadURL(raw);
}

function guestExtensionDirs(): string[] {
  const remote = cachedMeifannaoDir();
  return remote && existsSync(join(remote, "manifest.json")) ? [remote] : [];
}

function toGuestExtension(ext: Extension): GuestBrowserExtension {
  const manifest = ext.manifest as {
    action?: { default_popup?: string; default_icon?: Record<string, string> | string };
    icons?: Record<string, string>;
  };
  const popup = manifest.action?.default_popup?.trim() ?? "";
  const icons = manifest.action?.default_icon;
  const iconRel =
    (typeof icons === "string" ? icons : icons?.["38"] || icons?.["64"] || icons?.["32"]) ||
    manifest.icons?.["38"] ||
    manifest.icons?.["64"] ||
    "";
  const iconFile = iconRel ? join(ext.path, iconRel) : "";
  return {
    id: ext.id,
    name: ext.name || "扩展",
    popupUrl: popup
      ? `chrome-extension://${ext.id}/${popup.replace(/^\//, "")}`
      : "",
    iconDataUrl:
      iconFile && existsSync(iconFile)
        ? `data:${iconFile.endsWith(".svg") ? "image/svg+xml" : "image/png"};base64,${readFileSync(iconFile).toString("base64")}`
        : "",
  };
}

