function sanitizeBounds(bounds: GuestBrowserBounds): GuestBrowserBounds {
  return {
    x: Math.max(0, Math.round(bounds.x)),
    y: Math.max(0, Math.round(bounds.y)),
    width: Math.max(0, Math.round(bounds.width)),
    height: Math.max(0, Math.round(bounds.height)),
  };
}

function normalizeBrowserUrl(raw: string): string {
  const value = raw.trim();
  if (!value) return guestNewtabUrl();
  const alias = value.toLowerCase();
  if (alias === "qiwork://history" || alias === "qiwork://history/") {
    return guestHistoryUrl();
  }
  if (alias === "qiwork://downloads" || alias === "qiwork://downloads/") {
    return guestDownloadsUrl();
  }
  if (alias === "qiwork://newtab" || alias === "qiwork://newtab/" || alias === "about:newtab") {
    return guestNewtabUrl();
  }
  if (/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(value)) {
    try {
      if (new URL(value).protocol === "file:") return "";
    } catch {
      return "";
    }
    return classifyGuestUrl(value) === "navigate" && !isInternalAlias(value)
      ? value
      : "";
  }
  if (value.includes(" ") || !value.includes(".")) {
    return `https://www.google.com/search?q=${encodeURIComponent(value)}`;
  }
  return `https://${value}`;
}

function isBlankUrl(url: string): boolean {
  return !url || url === "about:blank" || guestInternalKind(url) === "newtab";
}

type WorkbenchKey = "bi" | "industry";

function workbenchKeyOf(redirect: string): WorkbenchKey {
  return redirect.startsWith("/industry") ? "industry" : "bi";
}

function displayUrl(url: string): string {
  if (isBlankUrl(url)) return "";
  if (isCertWarningUrl(url)) return certOriginalUrl(url) || "连接不是私密连接";
  const kind = guestInternalKind(url);
  if (kind === "history") return "qiwork://history";
  if (kind === "downloads") return "qiwork://downloads";
  return url;
}

function displayTitle(url: string, title: string): string {
  if (isBlankUrl(url)) return "首页";
  if (isCertWarningUrl(url)) return "连接不是私密连接";
  const kind = guestInternalKind(url);
  if (kind === "history") return "历史记录";
  if (kind === "downloads") return "下载记录与设置";
  return title || url;
}

async function resolveBiSsoUrl(redirect: string): Promise<string> {
  const port = sidecar.getRuntimeState().backend.port;
  if (!port) throw new Error("backend not ready");
  const query = new URLSearchParams({ redirect, layout: "sidebar" });
  const target = `http://127.0.0.1:${port}/api/v1/auth/bi-sso-url?${query}`;
  const res = await session.defaultSession.fetch(target);
  if (!res.ok) throw new Error(`sso ${res.status}`);
  const data = (await res.json()) as { url?: string };
  if (!data.url) throw new Error("missing sso url");
  return data.url;
}

function hasSsoTicket(url: string): boolean {
  return url.toLowerCase().includes("ticket=");
}

function needsFreshSso(url: string): boolean {
  if (isBlankUrl(url)) return true;
  return url.toLowerCase().includes("invalid_ticket");
}

function isWorkbenchSettled(url: string): boolean {
  return !isBlankUrl(url) && !hasSsoTicket(url);
}

function enforceGroupContiguity(
  order: string[],
  groupOf: (id: string) => string | null,
): string[] {
  const result: string[] = [];
  const placed = new Set<string>();
  for (const id of order) {
    const gid = groupOf(id);
    if (!gid) {
      result.push(id);
      continue;
    }
    if (placed.has(gid)) continue;
    placed.add(gid);
    for (const other of order) {
      if (groupOf(other) === gid) result.push(other);
    }
  }
  return result;
}

function persistPath(name: string): string {
  return join(app.getPath("userData"), "guest-browser", name);
}

function isUsableDirectory(dir: string): boolean {
  try {
    return Boolean(dir) && existsSync(dir) && statSync(dir).isDirectory();
  } catch {
    return false;
  }
}

function readJson<T>(file: string, fallback: T): T {
  try {
    if (!existsSync(file)) return fallback;
    return JSON.parse(readFileSync(file, "utf8")) as T;
  } catch {
    return fallback;
  }
}

function writeJson(file: string, value: unknown): void {
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, JSON.stringify(value));
}

const ZOOM_STEPS = [25, 33, 50, 67, 75, 80, 90, 100, 110, 125, 150, 175, 200, 250, 300, 400, 500];

type GuestSettings = {
  askWhereToSave?: boolean;
  showWhenComplete?: boolean;
  downloadDirectory?: string;
  doubleClickClosesTab?: boolean;
  hardwareAccelerationEnabled?: boolean;
  bookmarksBar?: boolean;
  zoomPercent?: number;
  bookmarks?: GuestBrowserBookmark[];
  certExceptions?: string[];
};

type BrowserSourceDef = { id: string; name: string; rel: string };

function clampZoom(value: number): number {
  if (!Number.isFinite(value)) return 100;
  return Math.max(ZOOM_STEPS[0], Math.min(ZOOM_STEPS[ZOOM_STEPS.length - 1], Math.round(value)));
}

function nextZoom(current: number, dir: "in" | "out"): number {
  let nearest = 0;
  for (let i = 1; i < ZOOM_STEPS.length; i += 1) {
    if (Math.abs(ZOOM_STEPS[i] - current) < Math.abs(ZOOM_STEPS[nearest] - current)) nearest = i;
  }
  const next = Math.max(0, Math.min(ZOOM_STEPS.length - 1, nearest + (dir === "in" ? 1 : -1)));
  return ZOOM_STEPS[next];
}

function sanitizeBookmarks(items: GuestBrowserBookmark[]): GuestBrowserBookmark[] {
  return items
    .filter((item) => item?.url)
    .map((item) => ({
      id: item.id || randomUUID(),
      title: item.title?.trim() || item.url,
      url: item.url.trim(),
    }));
}

function hostOf(url: string): string {
  try {
    return new URL(url).host;
  } catch {
    return "";
  }
}

function originOf(url: string): string {
  try {
    return new URL(url).origin;
  } catch {
    return url;
  }
}

function rangeCutoff(range: GuestBrowserClearRange): number | null {
  const now = Date.now();
  if (range === "all") return null;
  const span =
    range === "last-15min"
      ? 15 * 60 * 1000
      : range === "last-hour"
        ? 60 * 60 * 1000
        : range === "last-24h"
          ? 24 * 60 * 60 * 1000
          : range === "last-7d"
            ? 7 * 24 * 60 * 60 * 1000
            : 28 * 24 * 60 * 60 * 1000;
  return now - span;
}

function browserSourceDefs(): BrowserSourceDef[] {
  const home = app.getPath("home");
  if (process.platform === "darwin") {
    return [
      { id: "chrome", name: "Chrome", rel: join(home, "Library/Application Support/Google/Chrome/Default/Bookmarks") },
      { id: "edge", name: "Edge", rel: join(home, "Library/Application Support/Microsoft Edge/Default/Bookmarks") },
      { id: "brave", name: "Brave", rel: join(home, "Library/Application Support/BraveSoftware/Brave-Browser/Default/Bookmarks") },
      { id: "arc", name: "Arc", rel: join(home, "Library/Application Support/Arc/User Data/Default/Bookmarks") },
    ];
  }
  if (process.platform === "win32") {
    const local = process.env.LOCALAPPDATA ?? "";
    return [
      { id: "chrome", name: "Chrome", rel: join(local, "Google/Chrome/User Data/Default/Bookmarks") },
      { id: "edge", name: "Edge", rel: join(local, "Microsoft/Edge/User Data/Default/Bookmarks") },
    ];
  }
  const config = process.env.XDG_CONFIG_HOME ?? join(home, ".config");
  return [
    { id: "chrome", name: "Chrome", rel: join(config, "google-chrome/Default/Bookmarks") },
    { id: "edge", name: "Edge", rel: join(config, "microsoft-edge/Default/Bookmarks") },
  ];
}

function sourcePath(id: string): string {
  return browserSourceDefs().find((item) => item.id === id)?.rel ?? "";
}

function flattenChromeBookmarks(node: unknown, out: GuestBrowserBookmark[]): void {
  if (!node || typeof node !== "object") return;
  const item = node as { type?: string; name?: string; url?: string; children?: unknown[] };
  if (item.type === "url" && item.url) {
    out.push({ id: randomUUID(), title: item.name || item.url, url: item.url });
  }
  for (const child of item.children ?? []) flattenChromeBookmarks(child, out);
}

function readChromeBookmarkFile(file: string): GuestBrowserBookmark[] {
  if (!file || !existsSync(file)) return [];
  try {
    const data = JSON.parse(readFileSync(file, "utf8")) as { roots?: Record<string, unknown> };
    const out: GuestBrowserBookmark[] = [];
    for (const root of Object.values(data.roots ?? {})) flattenChromeBookmarks(root, out);
    return out;
  } catch {
    return [];
  }
}

function listBrowserImportSources(): GuestBrowserImportSource[] {
  return browserSourceDefs()
    .filter((item) => existsSync(item.rel))
    .map((item) => ({
      id: item.id,
      name: item.name,
      count: readChromeBookmarkFile(item.rel).length,
    }))
    .filter((item) => item.count > 0);
}

function parseBookmarkHtml(html: string): GuestBrowserBookmark[] {
  const out: GuestBrowserBookmark[] = [];
  const re = /<a[^>]+href=["']([^"']+)["'][^>]*>([^<]*)<\/a>/gi;
  let match: RegExpExecArray | null = re.exec(html);
  while (match) {
    const url = match[1]?.trim();
    if (url && /^https?:/i.test(url)) {
      out.push({ id: randomUUID(), title: match[2]?.trim() || url, url });
    }
    match = re.exec(html);
  }
  return out;
}

export function applyHardwareAccelerationPreference(): void {
  try {
    const settings = readJson<GuestSettings>(
      join(app.getPath("userData"), "guest-browser", "settings.json"),
      {},
    );
    if (settings.hardwareAccelerationEnabled === false) {
      app.disableHardwareAcceleration();
    }
  } catch {
    /* default on */
  }
}

