export type GuestUrlAction = "navigate" | "external" | "block";

const INTERNAL_ALIASES = new Set([
  "qiwork://newtab",
  "qiwork://newtab/",
  "about:newtab",
  "qiwork://history",
  "qiwork://history/",
  "qiwork://downloads",
  "qiwork://downloads/",
]);

const NAVIGATE = new Set([
  "http:",
  "https:",
  "chrome-extension:",
  "about:",
  "blob:",
  "data:",
]);

const EXTERNAL = new Set(["mailto:", "tel:", "weixin:"]);

export function isInternalAlias(raw: string): boolean {
  return INTERNAL_ALIASES.has(raw.trim().toLowerCase());
}

export function isGuestInternalPageUrl(raw: string): boolean {
  if (
    !/(?:^|[\\/])desktop-(newtab|history|downloads|cert-warning)\.html(?:[?#]|$)/.test(raw)
  ) {
    return false;
  }
  try {
    const protocol = new URL(raw).protocol;
    return protocol === "file:" || protocol === "http:" || protocol === "https:";
  } catch {
    return false;
  }
}

/**
 * Dabi guest policy: typed aliases and our own loadFile identity stay in-process.
 * Arbitrary file:// is blocked; only desktop-*.html is allowed (will-navigate after loadFile).
 */
export function classifyGuestUrl(raw: string): GuestUrlAction {
  const value = raw.trim();
  if (!value) return "block";
  if (isInternalAlias(value) || isGuestInternalPageUrl(value)) {
    return "navigate";
  }
  try {
    const protocol = new URL(value).protocol;
    if (NAVIGATE.has(protocol)) return "navigate";
    if (EXTERNAL.has(protocol)) return "external";
    return "block";
  } catch {
    return "block";
  }
}
