import { createWriteStream } from "node:fs";
import {
  mkdirSync,
  readFileSync,
  renameSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { mkdir, writeFile } from "node:fs/promises";
import { dirname, join, normalize, sep } from "node:path";
import { pipeline } from "node:stream/promises";
import { Readable } from "node:stream";
import { net } from "electron";
import JSZip from "jszip";
import {
  MEIFANNAO_CATALOG_URL,
  MEIFANNAO_EXTENSION_ID,
  adaptGuestExtensionManifest,
  findExtensionRoot,
  pickMeifannaoPack,
  safeZipEntryPath,
  type GuestExtensionPack,
} from "./guest-extension-pack";
import { userGuestExtensionDir } from "./paths";

const META_FILE = "qiwork-sync.json";

export type GuestExtensionSyncResult = {
  dir: string | null;
  changed: boolean;
};

function readMeta(dir: string): GuestExtensionPack | null {
  try {
    const raw = JSON.parse(
      readFileSync(join(dir, META_FILE), "utf8"),
    ) as Partial<GuestExtensionPack>;
    if (typeof raw.url !== "string" || typeof raw.version !== "string") {
      return null;
    }
    return { url: raw.url, version: raw.version };
  } catch {
    return null;
  }
}

async function fetchJson(url: string): Promise<unknown> {
  const response = await net.fetch(url, { method: "GET" });
  if (!response.ok) {
    throw new Error(`catalog request failed (${response.status})`);
  }
  return response.json();
}

async function downloadHttpsFile(url: string, filePath: string): Promise<void> {
  const parsed = new URL(url);
  if (parsed.protocol !== "https:") {
    throw new Error("extension pack must be https");
  }
  await mkdir(dirname(filePath), { recursive: true });
  const response = await net.fetch(parsed.toString(), { method: "GET" });
  if (!response.ok || !response.body) {
    throw new Error(`extension download failed (${response.status})`);
  }
  const nodeStream = Readable.fromWeb(
    response.body as import("node:stream/web").ReadableStream,
  );
  await pipeline(nodeStream, createWriteStream(filePath));
}

async function extractZip(zipPath: string, dest: string): Promise<void> {
  mkdirSync(dest, { recursive: true });
  const destRoot = normalize(dest);
  const zip = await JSZip.loadAsync(readFileSync(zipPath));
  for (const [name, entry] of Object.entries(zip.files)) {
    if (entry.dir) continue;
    const rel = safeZipEntryPath(name);
    if (!rel) continue;
    const out = join(dest, ...rel.split("/"));
    const normalized = normalize(out);
    if (normalized !== destRoot && !normalized.startsWith(destRoot + sep)) {
      continue;
    }
    await mkdir(dirname(out), { recursive: true });
    await writeFile(out, await entry.async("nodebuffer"));
  }
}

function replaceDir(from: string, to: string): void {
  rmSync(to, { recursive: true, force: true });
  mkdirSync(dirname(to), { recursive: true });
  renameSync(from, to);
}

export function cachedMeifannaoDir(): string | null {
  const dir = findExtensionRoot(userGuestExtensionDir(MEIFANNAO_EXTENSION_ID));
  if (dir) adaptGuestExtensionManifest(dir);
  return dir;
}

/** Download the official pack when missing or newer. */
export async function syncMeifannaoExtension(): Promise<GuestExtensionSyncResult> {
  const installDir = userGuestExtensionDir(MEIFANNAO_EXTENSION_ID);
  const cached = findExtensionRoot(installDir);
  const pack = pickMeifannaoPack(await fetchJson(MEIFANNAO_CATALOG_URL));
  if (!pack) return { dir: cached, changed: false };

  const current = readMeta(installDir);
  if (
    current?.url === pack.url &&
    current.version === pack.version &&
    cached
  ) {
    return { dir: cached, changed: false };
  }

  const staging = `${installDir}.next`;
  const zipPath = `${installDir}.zip`;
  rmSync(staging, { recursive: true, force: true });
  try {
    await downloadHttpsFile(pack.url, zipPath);
    await extractZip(zipPath, staging);
    const unpacked = findExtensionRoot(staging);
    if (!unpacked) {
      throw new Error("extension pack has no manifest.json");
    }
    if (unpacked !== staging) {
      const ready = `${staging}.ready`;
      rmSync(ready, { recursive: true, force: true });
      replaceDir(unpacked, ready);
      rmSync(staging, { recursive: true, force: true });
      replaceDir(ready, installDir);
    } else {
      replaceDir(staging, installDir);
    }
    const unpackedDir = findExtensionRoot(installDir);
    if (unpackedDir) adaptGuestExtensionManifest(unpackedDir);
    writeFileSync(join(installDir, META_FILE), JSON.stringify(pack));
  } finally {
    rmSync(zipPath, { force: true });
    rmSync(staging, { recursive: true, force: true });
    rmSync(`${staging}.ready`, { recursive: true, force: true });
  }
  return { dir: findExtensionRoot(installDir), changed: true };
}
