import { app, BrowserWindow, clipboard, ipcMain, session, type Session } from "electron";
import {
  APP_DISPLAY_NAME,
  setupAboutPanel,
  setupApplicationBranding,
  setupMacApplicationMenu,
} from "./app-menu";
import { relaxResponseHeaders } from "./csp";
import { applyDockIcon, loadAppIcon } from "./app-icon";
import { releaseIdleSleep, setIdleSleepPrevention } from "./idle-sleep";
import { getUiLanguage, setUiLanguage } from "./prefs";
import { applyHardwareAccelerationPreference, guestBrowser } from "./guest-browser";
import { preloadPath, isDev } from "./paths";
import { parseUpdatePromptPayload } from "@qiwork/desktop-runtime/bridge";
import { IpcInvoke } from "@qiwork/desktop-runtime/ipcEvents";
import { registerAppProtocolHandler, registerAppScheme } from "./protocol";
import { downloadBackendFile } from "./download";
import {
  allowBackendForeground,
  openExternalLink,
  openFile,
  openFolder,
  showOpenDialog,
  showSaveDialog,
} from "./shell";
import { handleDeepLinkArgv, registerDeepLinkHandlers } from "./deep-link";
import { showDesktopNotification } from "./notifications";
import { platformLoginHost } from "./platform-login-host";
import { sidecar } from "./sidecar";
import { setupTray } from "./tray";
import { enableQuitIntercept, requestAppQuit, shouldInterceptQuit } from "./app-quit";
import { checkForUpdates, downloadUpdate, setupAutoUpdater } from "./updater";
import { getUpdatePromptWindow } from "./update-prompt";
import {
  closeWindow,
  focusMainWindow,
  minimizeWindow,
  openDevTools,
  permitExit,
  setupWindowLifecycle,
  toggleMaximizeWindow,
} from "./window";

setupApplicationBranding();
applyHardwareAccelerationPreference();

const UNRESTRICTED_HEADERS = Symbol.for("qiwork.unrestrictedHeaders");

function attachUnrestrictedHeaders(sess: Session): void {
  const marked = sess as Session & { [UNRESTRICTED_HEADERS]?: boolean };
  if (marked[UNRESTRICTED_HEADERS]) return;
  marked[UNRESTRICTED_HEADERS] = true;
  sess.webRequest.onHeadersReceived((details, callback) => {
    callback({
      responseHeaders: relaxResponseHeaders(details.responseHeaders),
    });
  });
}

app.on("session-created", attachUnrestrictedHeaders);

// VS Code–style: bypass system proxy for loopback
app.commandLine.appendSwitch(
  "proxy-bypass-list",
  "<local>;127.0.0.1;localhost;::1",
);
app.commandLine.appendSwitch("no-proxy-server");

registerAppScheme();

/** Overlay traffic lights onto the custom bar (`hidden`, not `hiddenInset`). */
const MAC_TRAFFIC_LIGHT_POSITION = { x: 14, y: 11 } as const;
/** Match `--yw-bg-layout` in variables.css / title bar less */
const DESKTOP_CHROME_BG = "#f2f3f8";

let mainWindow: BrowserWindow | null = null;
let ipcRegistered = false;

const gotLock = app.requestSingleInstanceLock();
if (!gotLock) {
  app.quit();
} else {
  app.on("second-instance", (_event, argv) => {
    handleDeepLinkArgv(argv, () => mainWindow);
    focusMainWindow(mainWindow);
  });
  registerDeepLinkHandlers(() => mainWindow);

  app.whenReady().then(() => {
    enableQuitIntercept();
    attachUnrestrictedHeaders(session.defaultSession);
    setupAboutPanel();
    setupMacApplicationMenu();
    void createWindow();
    app.on("activate", () => {
      if (BrowserWindow.getAllWindows().length === 0) {
        void createWindow();
      } else {
        focusMainWindow(mainWindow);
      }
    });
  });
}

function registerIpc(win: BrowserWindow): void {
  // Handlers that close over `win` need refresh; channel registration is once.
  const bindWindowHandlers = () => {
    ipcMain.removeHandler(IpcInvoke.restartBackend);
    ipcMain.removeHandler(IpcInvoke.windowMinimize);
    ipcMain.removeHandler(IpcInvoke.windowToggleMaximize);
    ipcMain.removeHandler(IpcInvoke.windowClose);
    ipcMain.removeHandler(IpcInvoke.openDevtools);
    ipcMain.removeHandler(IpcInvoke.updaterQuitAndInstall);
    ipcMain.removeHandler(IpcInvoke.guestBrowserShow);
    ipcMain.removeHandler(IpcInvoke.guestBrowserHide);
    ipcMain.removeHandler(IpcInvoke.guestBrowserSetBounds);
    ipcMain.removeHandler(IpcInvoke.guestBrowserSnapshot);
    ipcMain.removeHandler(IpcInvoke.guestBrowserNewTab);
    ipcMain.removeHandler(IpcInvoke.guestBrowserCloseTab);
    ipcMain.removeHandler(IpcInvoke.guestBrowserSwitchTab);
    ipcMain.removeHandler(IpcInvoke.guestBrowserNavigate);
    ipcMain.removeHandler(IpcInvoke.guestBrowserBack);
    ipcMain.removeHandler(IpcInvoke.guestBrowserForward);
    ipcMain.removeHandler(IpcInvoke.guestBrowserReload);
    ipcMain.removeHandler(IpcInvoke.guestBrowserHome);
    ipcMain.removeHandler(IpcInvoke.guestBrowserStop);
    ipcMain.removeHandler(IpcInvoke.guestBrowserCommand);

    ipcMain.handle(IpcInvoke.restartBackend, async () => {
      await sidecar.restart(win);
    });
    ipcMain.handle(IpcInvoke.windowMinimize, () => minimizeWindow(win));
    ipcMain.handle(IpcInvoke.windowToggleMaximize, () =>
      toggleMaximizeWindow(win),
    );
    ipcMain.handle(IpcInvoke.windowClose, () => closeWindow(win));
    ipcMain.handle(IpcInvoke.openDevtools, () => openDevTools(win));
    ipcMain.handle(IpcInvoke.updaterQuitAndInstall, async () => {
      await requestAppQuit({ applyUpdate: true, requireReady: true });
    });
    ipcMain.handle(
      IpcInvoke.guestBrowserShow,
      (_e, args: { bounds?: unknown }) => {
        const bounds = parseGuestBounds(args?.bounds);
        if (!bounds) return guestBrowser.snapshot();
        return guestBrowser.show(win, bounds);
      },
    );
    ipcMain.handle(IpcInvoke.guestBrowserHide, () => {
      guestBrowser.hide();
    });
    ipcMain.handle(IpcInvoke.guestBrowserSetBounds, (_e, bounds: unknown) => {
      const next = parseGuestBounds(bounds);
      if (next) guestBrowser.setBounds(next);
    });
    ipcMain.handle(IpcInvoke.guestBrowserSnapshot, () => guestBrowser.snapshot());
    ipcMain.handle(IpcInvoke.guestBrowserNewTab, (_e, args?: { url?: string }) =>
      guestBrowser.newTab(args?.url),
    );
    ipcMain.handle(IpcInvoke.guestBrowserCloseTab, (_e, args: { id?: string }) =>
      args?.id ? guestBrowser.closeTab(args.id) : guestBrowser.snapshot(),
    );
    ipcMain.handle(IpcInvoke.guestBrowserSwitchTab, (_e, args: { id?: string }) =>
      args?.id ? guestBrowser.switchTab(args.id) : guestBrowser.snapshot(),
    );
    ipcMain.handle(IpcInvoke.guestBrowserNavigate, (_e, args: { url?: string }) =>
      guestBrowser.navigate(typeof args?.url === "string" ? args.url : ""),
    );
    ipcMain.handle(IpcInvoke.guestBrowserBack, () => guestBrowser.goBack());
    ipcMain.handle(IpcInvoke.guestBrowserForward, () => guestBrowser.goForward());
    ipcMain.handle(IpcInvoke.guestBrowserReload, () => guestBrowser.reload());
    ipcMain.handle(IpcInvoke.guestBrowserHome, () => guestBrowser.goHome());
    ipcMain.handle(IpcInvoke.guestBrowserStop, () => guestBrowser.stop());
    ipcMain.handle(IpcInvoke.guestBrowserCommand, (_e, cmd: unknown) =>
      guestBrowser.command(cmd as Parameters<typeof guestBrowser.command>[0]),
    );
    ipcMain.removeHandler(IpcInvoke.guestBrowserOverlayReady);
    ipcMain.handle(IpcInvoke.guestBrowserOverlayReady, () => {
      guestBrowser.markOverlayReady();
    });
  };

  if (ipcRegistered) {
    bindWindowHandlers();
    return;
  }
  ipcRegistered = true;

  ipcMain.handle(IpcInvoke.runtimeState, () => sidecar.getRuntimeState());

  ipcMain.handle(IpcInvoke.allowBackendForeground, () =>
    allowBackendForeground(),
  );
  ipcMain.handle(IpcInvoke.openFolder, (_e, args: { path: string }) =>
    openFolder(args.path),
  );
  ipcMain.handle(IpcInvoke.openFile, (_e, args: { path: string }) =>
    openFile(args.path),
  );
  ipcMain.handle(IpcInvoke.openExternalLink, (_e, args: { url: string }) =>
    openExternalLink(args.url),
  );

  ipcMain.handle(IpcInvoke.getUiLanguage, () => getUiLanguage());
  ipcMain.handle(IpcInvoke.setUiLanguage, (_e, args: { language: string }) => {
    setUiLanguage(args.language);
  });
  ipcMain.handle(
    IpcInvoke.setIdleSleepPrevention,
    (_e, args: { enabled: boolean }) => setIdleSleepPrevention(args.enabled),
  );

  ipcMain.handle(
    IpcInvoke.showOpenDialog,
    (_e, args?: { directory?: boolean; title?: string }) =>
      showOpenDialog(args),
  );
  ipcMain.handle(
    IpcInvoke.showSaveDialog,
    (_e, args?: { defaultPath?: string; title?: string }) =>
      showSaveDialog(args),
  );
  ipcMain.handle(
    IpcInvoke.downloadBackendFile,
    (
      _e,
      args: { url: string; filePath: string; headers?: Record<string, string> },
    ) => downloadBackendFile(args),
  );
  ipcMain.handle(IpcInvoke.getAppVersion, () => app.getVersion());
  ipcMain.handle(IpcInvoke.updaterCheck, (event) =>
    checkForUpdates(BrowserWindow.fromWebContents(event.sender)),
  );
  ipcMain.handle(IpcInvoke.updaterDownload, (event) =>
    downloadUpdate(BrowserWindow.fromWebContents(event.sender)),
  );
  ipcMain.handle(
    IpcInvoke.showNotification,
    (_e, args: { title: string; body: string }) => {
      showDesktopNotification(args.title, args.body);
    },
  );
  ipcMain.handle(IpcInvoke.clipboardWriteText, (_e, args: { text: string }) => {
    clipboard.writeText(typeof args?.text === "string" ? args.text : "");
  });
  ipcMain.removeHandler(IpcInvoke.updatePromptSet);
  ipcMain.handle(IpcInvoke.updatePromptSet, (event, raw: unknown) => {
    const payload = parseUpdatePromptPayload(raw);
    if (!payload) return;
    getUpdatePromptWindow().set(payload, event.sender);
  });

  bindWindowHandlers();
}

function parseGuestBounds(raw: unknown): {
  x: number;
  y: number;
  width: number;
  height: number;
} | null {
  if (!raw || typeof raw !== "object") return null;
  const rec = raw as Record<string, unknown>;
  const { x, y, width, height } = rec;
  if (
    typeof x !== "number" ||
    typeof y !== "number" ||
    typeof width !== "number" ||
    typeof height !== "number"
  ) {
    return null;
  }
  return { x, y, width, height };
}

async function createWindow(): Promise<void> {
  registerAppProtocolHandler();

  const appIcon = loadAppIcon();
  const win = new BrowserWindow({
    width: 1480,
    height: 850,
    minWidth: 600,
    minHeight: 600,
    title: APP_DISPLAY_NAME,
    backgroundColor: DESKTOP_CHROME_BG,
    show: true,
    ...(process.platform === "win32" && !appIcon.isEmpty()
      ? { icon: appIcon }
      : {}),
    ...(process.platform === "darwin"
      ? {
          titleBarStyle: "hidden" as const,
          trafficLightPosition: MAC_TRAFFIC_LIGHT_POSITION,
        }
      : {}),
    ...(process.platform === "win32" ? { frame: false } : {}),
    webPreferences: {
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: false,
      webSecurity: false,
      preload: preloadPath(),
    },
  });

  mainWindow = win;
  guestBrowser.attach(win);
  setupWindowLifecycle(win);
  setupTray(win);
  registerIpc(win);

  // Load the renderer before spawn so it can subscribe to runtime-state.
  if (isDev()) {
    const viteUrl =
      process.env.VITE_DEV_SERVER_URL ?? "http://localhost:5173/electron.html";
    await win.loadURL(viteUrl);
  } else {
    await win.loadURL("app://localhost/electron.html");
  }

  const desktopHostEnv = await platformLoginHost.start(win);
  sidecar.setDesktopHostEnv(desktopHostEnv);
  await sidecar.start(win);
  void setupAutoUpdater(win);

  applyDockIcon(appIcon);
}

app.on("window-all-closed", () => {
  // Keep running in tray on all platforms; do not quit.
});

app.on("before-quit", (event) => {
  if (shouldInterceptQuit()) {
    event.preventDefault();
    void requestAppQuit({ applyUpdate: true });
    return;
  }
  permitExit();
  releaseIdleSleep();
  sidecar.stop();
  platformLoginHost.stop();
  guestBrowser.destroy();
  getUpdatePromptWindow().destroy();
});
