import { Menu, Tray, type BrowserWindow } from "electron";
import { requestAppQuit } from "./app-quit";
import { loadTrayIcon } from "./app-icon";

let tray: Tray | null = null;

function showMainWindow(win: BrowserWindow): void {
  if (win.isMinimized()) win.restore();
  win.show();
  win.focus();
}

export function setupTray(win: BrowserWindow): void {
  const image = loadTrayIcon();
  if (image.isEmpty()) {
    console.warn("[tray] skipped — icon file missing or unreadable");
    return;
  }

  tray = new Tray(image);
  tray.setToolTip("QIWork");
  tray.setContextMenu(
    Menu.buildFromTemplate([
      {
        label: "显示主窗口",
        click: () => showMainWindow(win),
      },
      { type: "separator" },
      {
        label: "退出",
        click: () => {
          void requestAppQuit({ applyUpdate: true });
        },
      },
    ]),
  );
  tray.on("click", () => showMainWindow(win));
}
