import fs from "node:fs";
import path from "node:path";
import { app, nativeImage, type NativeImage } from "electron";
import { electronDistDir, isDev } from "./paths";

function iconsDir(): string {
  const candidates = [
    path.join(app.getAppPath(), "build", "icons"),
    path.join(process.resourcesPath, "icons"),
    path.join(electronDistDir(), "..", "build", "icons"),
  ];
  return candidates.find((d) => fs.existsSync(d)) ?? candidates[0]!;
}

function loadFirstAvailableIcon(names: string[]): NativeImage {
  const dir = iconsDir();
  for (const name of names) {
    const full = path.join(dir, name);
    if (!fs.existsSync(full)) continue;
    const image = nativeImage.createFromPath(full);
    if (!image.isEmpty()) return image;
  }
  return nativeImage.createEmpty();
}

function appIconCandidates(): string[] {
  // `electron .` on macOS cannot decode .icns via nativeImage; PNG works.
  if (process.platform === "darwin" && isDev()) return ["icon.png", "icon.icns"];
  if (process.platform === "darwin") return ["icon.icns", "icon.png"];
  if (process.platform === "win32") return ["icon.ico", "icon.png"];
  return ["icon.png", "icon.icns"];
}

export function loadAppIcon(): NativeImage {
  return loadFirstAvailableIcon(appIconCandidates());
}

/** Filesystem path for About panel / other native chrome that needs a path. */
export function resolveAppIconPath(): string | undefined {
  const dir = iconsDir();
  for (const name of appIconCandidates()) {
    const full = path.join(dir, name);
    if (fs.existsSync(full)) return full;
  }
  return undefined;
}

export function loadTrayIcon(): NativeImage {
  const template = loadFirstAvailableIcon([
    "trayTemplate.png",
    "trayTemplate@2x.png",
  ]);
  if (!template.isEmpty()) {
    template.setTemplateImage(true);
    return template;
  }

  let image = loadFirstAvailableIcon(appIconCandidates());
  if (image.isEmpty() || process.platform !== "darwin") return image;

  const { width, height } = image.getSize();
  if (width > 22 || height > 22) {
    image = image.resize({ width: 22, height: 22 });
  }
  return image;
}

export function applyDockIcon(icon: NativeImage = loadAppIcon()): void {
  if (process.platform !== "darwin" || !app.dock || icon.isEmpty()) return;
  app.dock.setIcon(icon);
}
