/**
 * Desktop master key via Chromium safeStorage (Electron userData envelope).
 * Injected into Gateway + Connect sidecars as QIWORK_MASTER_KEY_HEX.
 * Never log the plaintext key.
 */
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { app, safeStorage } from "electron";

const CRYPTO_DIR = "crypto";
const ENVELOPE_FILE = "master_key.enc";
const PLAIN_FALLBACK_FILE = "master_key.plain";

let cachedHex: string | null = null;

function cryptoDir(): string {
  return path.join(app.getPath("userData"), CRYPTO_DIR);
}

function envelopePath(): string {
  return path.join(cryptoDir(), ENVELOPE_FILE);
}

function plainFallbackPath(): string {
  return path.join(cryptoDir(), PLAIN_FALLBACK_FILE);
}

function ensureDir(): void {
  fs.mkdirSync(cryptoDir(), { recursive: true });
}

function readEnvelope(): string | null {
  const p = envelopePath();
  if (!fs.existsSync(p)) return null;
  try {
    const b64 = fs.readFileSync(p, "utf8").trim();
    if (!b64) return null;
    const buf = Buffer.from(b64, "base64");
    const hex = safeStorage.decryptString(buf).trim();
    if (!/^[0-9a-f]{64}$/i.test(hex)) return null;
    return hex.toLowerCase();
  } catch (err) {
    console.error("[crypto] failed to decrypt master key envelope:", err);
    return null;
  }
}

function writeEnvelope(hex: string): void {
  ensureDir();
  const encrypted = safeStorage.encryptString(hex);
  fs.writeFileSync(envelopePath(), encrypted.toString("base64"), {
    mode: 0o600,
  });
}

function readPlainFallback(): string | null {
  const p = plainFallbackPath();
  if (!fs.existsSync(p)) return null;
  try {
    const hex = fs.readFileSync(p, "utf8").trim().toLowerCase();
    if (!/^[0-9a-f]{64}$/.test(hex)) return null;
    return hex;
  } catch {
    return null;
  }
}

function writePlainFallback(hex: string): void {
  ensureDir();
  console.warn(
    "[crypto] safeStorage unavailable; master key stored as plain file with mode 0600",
  );
  fs.writeFileSync(plainFallbackPath(), hex, { mode: 0o600 });
}

function generateHex(): string {
  return crypto.randomBytes(32).toString("hex");
}

/**
 * Return a stable 64-char hex master key for sidecar env injection.
 * Prefer safeStorage envelope; fall back to 0o600 plain file when encryption
 * is unavailable (typical headless Linux without libsecret).
 */
export function getOrCreateMasterKeyHex(): string {
  if (cachedHex) return cachedHex;

  if (safeStorage.isEncryptionAvailable()) {
    const existing = readEnvelope();
    if (existing) {
      cachedHex = existing;
      return cachedHex;
    }
    const hex = generateHex();
    writeEnvelope(hex);
    cachedHex = hex;
    return cachedHex;
  }

  const plain = readPlainFallback();
  if (plain) {
    cachedHex = plain;
    return cachedHex;
  }
  const hex = generateHex();
  writePlainFallback(hex);
  cachedHex = hex;
  return cachedHex;
}

/** Env vars to merge into Gateway and Connect spawn environments. */
export function cryptoEnv(): NodeJS.ProcessEnv {
  return {
    QIWORK_MASTER_KEY_HEX: getOrCreateMasterKeyHex(),
  };
}
