/** Derive electron-updater generic feed from the same LLMPlat URL as official.env. */

const FEED_SUFFIX = "/api/v1/client-releases/updates/";

export function parseLlmplatApiUrl(envText: string): string {
  let found = "";
  for (const raw of envText.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith("#")) continue;
    if (!line.startsWith("LLMPLAT_API_URL=")) continue;
    found = line
      .slice("LLMPLAT_API_URL=".length)
      .trim()
      .replace(/^['"]|['"]$/g, "");
  }
  return found.replace(/\/+$/, "");
}

export function updateFeedUrlFromApiBase(apiBase: string): string {
  return `${apiBase.replace(/\/+$/, "")}${FEED_SUFFIX}`;
}

export function resolveUpdateFeedUrl(
  env: NodeJS.ProcessEnv,
  officialText?: string,
): string | null {
  const fromEnv = env.LLMPLAT_API_URL?.trim().replace(/\/+$/, "") ?? "";
  const fromFile = officialText ? parseLlmplatApiUrl(officialText) : "";
  const base = fromEnv || fromFile;
  if (!base) return null;
  return updateFeedUrlFromApiBase(base);
}
