import fs from "node:fs";
import path from "node:path";
import { app } from "electron";
import {
  parseRestartMarker,
  type RestartMarker,
} from "@qiwork/desktop-runtime/updatePolicy";

const MARKER_FILE = "update-restart.json";

export function restartMarkerPath(): string {
  return path.join(app.getPath("userData"), MARKER_FILE);
}

export function readRestartMarker(filePath: string): RestartMarker | null {
  try {
    if (!fs.existsSync(filePath)) return null;
    return parseRestartMarker(JSON.parse(fs.readFileSync(filePath, "utf8")));
  } catch {
    return null;
  }
}

export function writeRestartMarker(
  filePath: string,
  marker: RestartMarker,
): void {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, JSON.stringify(marker), "utf8");
}

export function clearRestartMarker(filePath: string): void {
  try {
    fs.unlinkSync(filePath);
  } catch {
    /* already gone */
  }
}
