/**
 * Desktop supervisor snapshot. Main owns this; renderer subscribes.
 * HTTP is the data plane. This is the control plane.
 */

type BackendProcessState = "starting" | "up" | "failed";
type ConnectProcessState = "starting" | "up" | "degraded";
export type AgentCapState = "starting" | "ready" | "failed";

export type DesktopRuntimeState = {
  generation: number;
  backend: {
    state: BackendProcessState;
    port: number | null;
    error: string;
  };
  connect: {
    state: ConnectProcessState;
    port: number | null;
    error: string;
  };
  caps: {
    core: boolean;
    agent: AgentCapState;
    agentError: string;
  };
};

/** Parsed QIWORK-RUNTIME line, or a supervisor-observed process exit. */
export type RuntimeStateEvent =
  | { kind: "listen"; sidecar: "backend" | "connect"; port: number }
  | { kind: "cap"; cap: "core" | "agent" }
  | { kind: "fail"; sidecar: "backend" | "agent"; message: string }
  | { kind: "connect-degraded"; message: string }
  | { kind: "backend-exit"; message: string };

export function emptyRuntimeState(generation = 0): DesktopRuntimeState {
  return {
    generation,
    backend: { state: "starting", port: null, error: "" },
    connect: { state: "starting", port: null, error: "" },
    caps: { core: false, agent: "starting", agentError: "" },
  };
}

export function isAgentReady(state: DesktopRuntimeState): boolean {
  return state.caps.agent === "ready";
}

export function isDesktopRuntimeState(
  value: unknown,
): value is DesktopRuntimeState {
  if (!value || typeof value !== "object") return false;
  const rec = value as DesktopRuntimeState;
  return (
    Number.isSafeInteger(rec.generation) &&
    rec.generation >= 0 &&
    !!rec.backend &&
    (rec.backend.state === "starting" ||
      rec.backend.state === "up" ||
      rec.backend.state === "failed") &&
    (rec.backend.port === null || typeof rec.backend.port === "number") &&
    typeof rec.backend.error === "string" &&
    !!rec.connect &&
    (rec.connect.state === "starting" ||
      rec.connect.state === "up" ||
      rec.connect.state === "degraded") &&
    (rec.connect.port === null || typeof rec.connect.port === "number") &&
    typeof rec.connect.error === "string" &&
    !!rec.caps &&
    typeof rec.caps.core === "boolean" &&
    (rec.caps.agent === "starting" ||
      rec.caps.agent === "ready" ||
      rec.caps.agent === "failed") &&
    typeof rec.caps.agentError === "string"
  );
}

function failBackend(
  state: DesktopRuntimeState,
  message: string,
): DesktopRuntimeState {
  if (state.backend.state === "failed") return state;
  return {
    ...state,
    backend: {
      ...state.backend,
      state: "failed",
      error: message,
    },
    caps: { core: false, agent: "starting", agentError: "" },
  };
}

/** Pure control-plane transitions. Sidecar applies these and publishes. */
export function reduceRuntimeState(
  state: DesktopRuntimeState,
  event: RuntimeStateEvent,
): DesktopRuntimeState {
  if (event.kind === "listen") {
    if (event.sidecar === "backend") {
      return {
        ...state,
        backend: { state: "up", port: event.port, error: "" },
      };
    }
    return {
      ...state,
      connect: { state: "up", port: event.port, error: "" },
    };
  }
  if (event.kind === "cap") {
    if (event.cap === "core") {
      return { ...state, caps: { ...state.caps, core: true } };
    }
    return {
      ...state,
      caps: { ...state.caps, agent: "ready", agentError: "" },
    };
  }
  if (event.kind === "fail") {
    if (event.sidecar === "backend") {
      return failBackend(state, event.message);
    }
    return {
      ...state,
      caps: {
        ...state.caps,
        agent: "failed",
        agentError: event.message,
      },
    };
  }
  if (event.kind === "connect-degraded") {
    return {
      ...state,
      connect: {
        ...state.connect,
        state: "degraded",
        error: event.message,
      },
    };
  }
  return failBackend(state, event.message);
}
