const allowed = new Set<string>();

export function loadCertExceptions(hosts: string[]): void {
  allowed.clear();
  for (const host of hosts) {
    const name = host.trim().toLowerCase();
    if (name) allowed.add(name);
  }
}

export function certExceptionHosts(): string[] {
  return [...allowed];
}

export function isCertAllowed(host: string): boolean {
  return Boolean(host) && allowed.has(host.trim().toLowerCase());
}

export function allowCertHost(host: string): void {
  const name = host.trim().toLowerCase();
  if (name) allowed.add(name);
}

export function isCertError(description: string): boolean {
  return /^ERR_CERT_/.test(description);
}

export function certOriginalUrl(href: string): string | null {
  try {
    return new URL(href).searchParams.get("url");
  } catch {
    return null;
  }
}

export function isCertWarningUrl(raw: string): boolean {
  return /(?:^|[\\/])desktop-cert-warning\.html(?:[?#]|$)/.test(raw);
}
