import { shell, type BrowserWindow } from "electron";

let allowExit = false;

export function permitExit(): void {
  allowExit = true;
}

export function revokeExit(): void {
  allowExit = false;
}

function isLoopbackUrl(raw: string): boolean {
  try {
    const url = new URL(raw);
    if (url.protocol === "app:") return true;
    if (url.protocol !== "http:" && url.protocol !== "https:") return false;
    return (
      url.hostname === "127.0.0.1" ||
      url.hostname === "localhost" ||
      url.hostname === "::1"
    );
  } catch {
    return false;
  }
}

export function setupWindowLifecycle(win: BrowserWindow): void {
  win.on("close", (event) => {
    if (allowExit) return;
    event.preventDefault();
    win.hide();
  });

  win.webContents.setWindowOpenHandler(({ url }) => {
    if (isLoopbackUrl(url)) {
      return { action: "allow" };
    }
    void shell.openExternal(url);
    return { action: "deny" };
  });

  win.webContents.on("will-navigate", (event, url) => {
    if (isLoopbackUrl(url) || url.startsWith("file:")) return;
    // Allow Vite HMR / electron.html origin in development.
    if (url.startsWith("http://localhost:") || url.startsWith("http://127.0.0.1:")) {
      return;
    }
    event.preventDefault();
    void shell.openExternal(url);
  });

  win.webContents.session.setPermissionRequestHandler(
    (_wc, permission, callback, details) => {
      const requestingUrl = details.requestingUrl || "";
      const allowMedia =
        permission === "media" && isLoopbackUrl(requestingUrl);
      callback(allowMedia);
    },
  );
}

export function focusMainWindow(win: BrowserWindow | null): void {
  if (!win) return;
  if (win.isMinimized()) win.restore();
  win.show();
  win.focus();
}

export function minimizeWindow(win: BrowserWindow): void {
  win.minimize();
}

export async function toggleMaximizeWindow(win: BrowserWindow): Promise<void> {
  if (win.isMaximized()) win.unmaximize();
  else win.maximize();
}

export function closeWindow(win: BrowserWindow): void {
  win.close();
}

export function openDevTools(win: BrowserWindow): void {
  win.webContents.openDevTools({ mode: "detach" });
}
